window.NIGHTS.cases[1]={"nr":1,"id":"case01","title":"Der sanfte Tod","subtitle":"Ein herzzerreißender Fall um gefühlvollen Jazz und drohenden Tod","level":"Persönliche Ebene","from":23,"to":40,"mythen":[],"sections":[{"id":"titel-und-pitch","kind":"intro","title":"Titel und Pitch","page":23,"layer":null,"blocks":3},{"id":"duett-mit-dem-kummer","kind":"place","title":"DUETT MIT DEM KUMMER","page":24,"layer":null,"blocks":3},{"id":"heilung-fuer-die-gebrochenen","kind":"place","title":"HEILUNG FÜR DIE GEBROCHENEN","page":24,"layer":null,"blocks":3},{"id":"in-der-zwischenzeit-eine-vision-des-todes","kind":"place","title":"IN DER ZWISCHENZEIT: EINE VISION DES TODES","page":24,"layer":null,"blocks":28},{"id":"schicht-0-aufhaenger","kind":"layer","title":"SCHICHT 0: AUFHÄNGER","page":27,"layer":null,"blocks":5},{"id":"schicht-1-trauer-um-die-vergangenheit","kind":"layer","title":"SCHICHT 1: TRAUER UM DIE VERGANGENHEIT","page":27,"layer":null,"blocks":2},{"id":"das-washboard","kind":"place","title":"DAS WASHBOARD","page":27,"layer":"schicht-1-trauer-um-die-vergangenheit","blocks":37},{"id":"das-bancroft-penthouse","kind":"place","title":"DAS BANCROFT-PENTHOUSE","page":31,"layer":"schicht-1-trauer-um-die-vergangenheit","blocks":19},{"id":"bestattungsinstitut-green-meadows","kind":"place","title":"BESTATTUNGSINSTITUT GREEN MEADOWS","page":32,"layer":"schicht-1-trauer-um-die-vergangenheit","blocks":13},{"id":"angriff-auf-martha","kind":"place","title":"ANGRIFF AUF MARTHA","page":33,"layer":"schicht-1-trauer-um-die-vergangenheit","blocks":11},{"id":"schicht-2-auf-taube-ohren","kind":"layer","title":"SCHICHT 2: AUF TAUBE OHREN","page":34,"layer":null,"blocks":1},{"id":"martha-ellis-garderobe","kind":"place","title":"MARTHA ELLIS‘ GARDEROBE","page":34,"layer":"schicht-2-auf-taube-ohren","blocks":6},{"id":"schweisserei-harrington","kind":"place","title":"SCHWEISSEREI HARRINGTON","page":34,"layer":"schicht-2-auf-taube-ohren","blocks":8},{"id":"greifer","kind":"place","title":"GREIFER","page":35,"layer":"schicht-2-auf-taube-ohren","blocks":7},{"id":"schicht-3-die-totenglocke","kind":"layer","title":"SCHICHT 3: DIE TOTENGLOCKE","page":36,"layer":null,"blocks":1},{"id":"nowaks-versteck","kind":"place","title":"NOWAKS VERSTECK","page":36,"layer":"schicht-3-die-totenglocke","blocks":19},{"id":"der-naechste-mord","kind":"place","title":"DER NÄCHSTE MORD","page":38,"layer":"schicht-3-die-totenglocke","blocks":13},{"id":"schicht-4-eine-toedliche-nacht-in-der-oper","kind":"layer","title":"SCHICHT 4: EINE TÖDLICHE NACHT IN DER OPER","page":39,"layer":null,"blocks":1},{"id":"das-opernhaus","kind":"place","title":"DAS OPERNHAUS","page":39,"layer":"schicht-4-eine-toedliche-nacht-in-der-oper","blocks":13},{"id":"abspann","kind":"abspann","title":"Abspann","page":40,"layer":null,"blocks":8}],"pages":{"23":{"tab":"","blocks":[{"t":"sh","x":"<b>EIN HERZZERREISSENDER FALL UM GEFÜHLVOLLEN JAZZ</b>","sz":20.0,"box":[105.6,774.0,489.9,794.0],"p":23,"i":0,"sec":"titel-und-pitch"}],"size":[595.276,841.89]},"24":{"tab":"","blocks":[{"t":"p","x":"Eine Jazzsängerin braucht Hilfe, um eine Reihe mysteriöser Morde aufzuklären, die sie wie ein bösartiger Geistertanz einkreisen. Von der Innenstadt bis in die Vorstädte sterben Menschen, die Hände in die Brust gekrallt, als wollten sie ihr gebrochenes Herz umklammern. Wird das Team in der Lage sein, die Bewohner der Stadt vor diesem unheimlichen Todesengel zu retten, während die Zahl der Opfer unaufhörlich steigt?","sz":13.0,"box":[53.9,60.1,284.3,218.1],"p":24,"i":0,"sec":"titel-und-pitch"},{"t":"p","x":"<i>Der sanfte Tod</i> ist ein klassischer Neo-Noir-Krimi, in dem das Team eine rätselhafte Mordserie aufklärt. Vor der Kulisse eines zwielichtigen Jazzclubs und dreckiger Gassen untersucht es Tatorte, trifft auf NSC aus verschiedenen Gesellschaftsschichten und trägt Konflikte mit suspekten Unterweltfiguren aus. Der Fall kann die Spieler:innen dazu bringen, einen NSC fälschlicherweise als Täter zu beschuldigen, während die wahre Verbrecher:in Unschuld vortäuscht und den Schutz des Teams sucht, um es eine Zeit lang zu täuschen.","sz":9.5,"box":[53.9,228.6,285.6,350.6],"p":24,"i":1,"sec":"titel-und-pitch"},{"t":"h","x":"DUETT MIT DEM KUMMER","sz":16.0,"box":[53.9,402.6,227.0,418.6],"p":24,"i":2,"skip":true,"sec":"duett-mit-dem-kummer"},{"t":"p","x":"<b>Martha Ellis</b> ist eine der besten Blues- und Jazzsängerinnen der Stadt, gesegnet mit einer herzzerreißenden Stimme, deren Erhabenheit nur von ihrer Melancholie übertroffen wird. Vielleicht liegt es an ihrer Vorliebe für traurigen Blues, dass Martha als Riss der <b>Banshee</b> erwacht ist, der klagenden irischen Todesfee, die vor Todesfällen in der Familie warnt. Nach dem Erwachen stellte sie fest, dass sie mit dem Gesang noch intensivere Emotionen wecken konnte als zuvor. Wo sie früher einigen empfindsamen Zuhörer:innen Tränen in die Augen trieb, konnte sie nun einen ganzen Saal voller Menschen in einen emotionalen Zusammenbruch stürzen.","sz":9.5,"box":[53.9,422.6,284.5,582.1],"p":24,"i":3,"sec":"duett-mit-dem-kummer"},{"t":"p","x":"Als es zum ersten Mal geschah, machte Marthas Manager die Sache publik und bezeichnete sie als „größte Soulstimme von Downtown„. Doch Martha hatte Mühe, ihre Kräfte im Zaum zu halten. Sie beherrschte die Emotionen ihres Publikums intuitiv, aber ihre eigene komplexe Gemütslage verleitete sie dazu, diese Kräfte in unguter Weise einzusetzen. Als nach erschütternden Erlebnissen immer weniger Menschen zu ihren Shows kamen, ging es mit Marthas Karriere bergab. Sie verfiel tiefer in Depressionen und Alkoholismus und geriet in Geldnot. Nur wenige Clubs und Konzertlocations wollten ihr noch eine Bühne bieten.","sz":9.5,"box":[53.9,590.7,286.0,737.7],"p":24,"i":4,"sec":"duett-mit-dem-kummer"},{"t":"h","x":"HEILUNG FÜR DIE GEBROCHENEN","sz":16.0,"box":[309.0,62.2,525.2,78.2],"p":24,"i":5,"skip":true,"sec":"heilung-fuer-die-gebrochenen"},{"t":"p","x":"Auf der Suche nach Beistand wandte sich Martha an <b>Dr. Selma Perrin</b>, eine Psychiaterin, die mit der Organisation „<b>Heilung für die Gebrochenen“</b> zusammenarbeitet, die Rissen Hilfe anbietet (s. S. 66). Indem sie ihre Kräfte positiv umdeutete, überzeugte Dr. Perrin Martha, dass ihre Lieder Menschen helfen konnten, verdrängten Kummer und den Schmerz zu fühlen. Marthas Aufgabe, ja Pflicht war es, deren Widerstand zu brechen und die Gefühle ans Licht zu holen, damit sie sich ihren verdrängten Traumata stellen konnten.","sz":9.5,"box":[309.0,82.2,541.2,204.2],"p":24,"i":6,"sec":"heilung-fuer-die-gebrochenen"},{"t":"p","x":"Dieses neue Selbstverständnis half Martha, sich aus dem Dunkel zu befreien, das sie umgab, und schenkte ihr neue Hoffnung. Sie konnte sich besser konzentrieren, und ihre Auftritte waren wieder ausgeglichener und angenehmer. Es gelang ihr, einen Stammplatz in dem zwielichtigen, aber stets gut besuchten Club <b>„Washboard“</b> zu bekommen. Während sie auf der Bühne stand, suchte sie im Publikum nach einer Person, deren Schmerz sie am eigenen Leib spürte und von der sie glaubte, sie brauche Hilfe. In Wirklichkeit zog ihre Mythos-Fähigkeit, einen baldigen Tod zu spüren, sie zu den Opfern hin. Sie ahnte nicht, dass sie selbst für den Untergang verantwortlich sein würde.","sz":9.5,"box":[309.0,212.8,538.6,372.3],"p":24,"i":7,"sec":"heilung-fuer-die-gebrochenen"},{"t":"h","x":"IN DER ZWISCHENZEIT: EINE VISION DES TODES","sz":16.0,"box":[309.0,388.0,464.1,421.0],"p":24,"i":8,"skip":true,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"Nicht weit vom Washboard entfernt, im Industriegebiet, fing <b>John Nowak</b>, ein taubstummer Fabrikarbeiter, ein Flugblatt auf, das im Wind wehte. Es war Reklame für das Washboard, mit Marthas Bild in der Mitte. Sobald sein Blick auf das Flugblatt fiel, erwachte Nowak als Riss des Gespenstes der kommenden Weihnacht (<i>Dickens‘ Weihnachtsgeschichte</i>). Sein Mythos zeigte ihm eine Vision von Martha Ellis‘ möglichem Tod und erfüllte ihn mit Kummer und Trauer über die Brutalität ihres Todes, das von ihr begangene Unrecht und den Hass, den man ihr entgegenbrachte. Nowak fühlte sich verpflichtet, Martha zu warnen. Er ließ alles stehen und liegen, verließ seinen Arbeitsplatz und machte sich auf den Weg zum Washboard.","sz":9.5,"box":[309.0,424.9,540.8,596.9],"p":24,"i":9,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"sh","x":"<b>DAS ERSTE OPFER</b>","sz":9.5,"box":[309.4,605.7,403.1,615.2],"p":24,"i":10,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"<b>Darnell Fox</b> saß an jenem Abend zusammen mit zwei befreundeten Paaren in der ersten Reihe im Washboard. Er fühlte sich als fünftes Rad am Wagen, war unglücklich und schüchtern. Den ganzen Abend über fühlte sich Martha von dem freundlichen Mann angezogen. Als die Einsamkeit ihn übermannte und er an die frische Luft ging, machte die Sängerin eine Pause und folgte ihm. Dort, in der Gasse, überredete sie ihn, für eine Privatvorstellung zu bleiben – sie würde nach Feierabend für ihn singen und versprach, es würde seine Stimmung bessern. Darnell willigte aus Höflichkeit ein, und sie trafen sich später auf der Bühne.","sz":9.5,"box":[309.0,623.8,539.4,770.8],"p":24,"i":11,"sec":"in-der-zwischenzeit-eine-vision-des-todes"}],"size":[595.276,841.89]},"25":{"tab":"","blocks":[{"t":"p","x":"Dort, im pathetischen Scheinwerferlicht, intonierte Martha für ihn das Klagelied der Banshee in seiner traurigsten Form, indem sie von einem Jungen sang, der niemanden sein eigen nennen konnte. Darnell brach zusammen, aufgewühlt vom Alleinsein, aber je mehr Martha sang, desto mehr schien er zu leiden. Der kathartische Moment, den Dr. Perrin versprochen hatte, blieb aus. Doch Martha konnte nicht aufhören. Sie sagte seinen Tod voraus, sang ihn herbei, bis sein Herz versagte und er an dem intensiven Kummer starb (unerklärliches Herzversagen, wie ein Leichenbeschauer der Schläfer:innen später sagen würde). Als dies geschah, bemerkte Martha am anderen Ende des Clubs John Nowak, den tätowierten Skinhead im Kapuzenpulli, der alles mit angesehen hatte. Nowak winkte und murmelte, um Martha vor der Zukunft zu warnen, die sie erwartete, wenn sie diesen Weg weitergehen würde. Seine Warnung stieß auf taube Ohren, da ihm die Worte fehlten. Martha versuchte, ihn zu Tode zu klagen, was ihr wegen seiner Taubheit nicht gelang, und schrie dann um Hilfe. Syrus, der Türsteher des Washboard, sah bei seinem Eintreffen den toten Gast auf dem Boden und eine verdächtige Kapuzengestalt, die vom Tatort floh.","sz":9.5,"box":[53.9,59.9,286.0,356.9],"p":25,"i":0,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"sh","x":"<b>WEITERES WEHKLAGEN</b>","sz":9.5,"box":[309.4,62.6,434.2,72.1],"p":25,"i":1,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"Martha war bestürzt über die Ereignisse und die unangenehme Lage, in der sie sich befand und wusste nicht, was sie tun sollte. Sie schwor sich, nie wieder mit Dr. Perrin zu sprechen und nie wieder das Lied der Banshee zu singen. Aber je mehr sie es verdrängte, desto mehr versuchte es, sich in ihre Auftritte zu drängen. Um ihre Karriere zu retten, musste sie einen Weg finden, der Banshee freien Lauf zu lassen. Bisher sind zwei weitere Opfer dem Klagelied zum Opfer gefallen: eine unglückliche Vorzeigefrau, die Ellis in ihrem Loft in der Innenstadt tötete, und ein Mann, der um seinen Sohn trauerte und starb, als die Sängerin bei dessen Beerdigung auftrat. In beiden Fällen war John Nowak Zeuge und versuchte, Martha von ihrem zerstörerischen Weg abzubringen. In beiden Fällen konnte Martha ihm den Tod in die Schuhe schieben oder sich zumindest auf seine Kosten aus der Schusslinie bringen. Die Polizei hat nun drei ungeklärte Todesfälle in Downtown, die mit Nowak in Verbindung stehen. Die Polizisten <b>Chaavi Das</b> (<i>Gramadevata</i>, der Schutzgeist einer Stadt im Hinduismus) und <b>Matt Quinn</b> (Schläfer) arbeiten an dem Fall und suchen nach ihrem Hauptverdächtigen, dem Skinhead mit der Kapuze.","sz":9.5,"box":[309.0,80.7,540.1,365.2],"p":25,"i":2,"sec":"in-der-zwischenzeit-eine-vision-des-todes"}],"size":[595.276,841.89]},"26":{"tab":"","blocks":[{"t":"h","x":"MARTHA","sz":23.0,"box":[53.9,63.4,138.5,86.4],"p":26,"i":0,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"Martha Ellis ist eine Frau Mitte 50, die tagsüber in ein fließendes, geblümtes Gewand und ein Kopftuch gehüllt ist und abends auf der Bühne in einem glitzernden Abendkleid ihre Kurven zeigt. Ihr Gebaren und die Kleidung vermitteln den Eindruck von Melancholie und Dramatik, von jemandem, dessen Zeit vorbei ist, aber immer noch an der Pracht der Vergangenheit festhält. Marthas bemitleidenswerter Zustand kommt stärker zur Geltung, wenn sie betrunken ist (was nur allzu oft der Fall ist). Im Rampenlicht jedoch geht ihre mitfühlende Art zu Herzen, und sie bringt ihr Publikum in eine schwermütige Stimmung.","sz":9.5,"box":[53.9,97.7,283.7,244.7],"p":26,"i":1,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"sh","x":"<b>MARTHA RICHTIG EINSETZEN</b>","sz":9.5,"box":[54.2,253.5,210.5,263.0],"p":26,"i":2,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"<b>Martha taucht während des gesamten Falles auf, quer durch alle Schichten.</b> Die SC werden vermutlich mehrere Interaktionen mit ihr haben, während sie den Fall untersuchen und sich der Verdacht, dass sie an den Todesfällen beteiligt ist, immer mehr erhärtet.","sz":9.5,"box":[53.9,271.6,286.3,331.0],"p":26,"i":3,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"<b>Versuche, Marthas Lügen zu nutzen, um die SC lange genug von der Wahrheit fernzuhalten</b>, damit die Geschichte weitergeht. Lass sie die Wahrheit herausfinden, wenn sie es sich redlich verdient haben. Vergiss nicht: Selbst wenn das Team Martha früh entlarvt, steht es vor der Herausforderung, ihr etwas nachzuweisen und sie aus dem Verkehr zu ziehen, ehe sie weiteren Schaden anrichten kann.","sz":9.5,"box":[53.9,339.8,282.2,436.7],"p":26,"i":4,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"<b>Um die Enthüllung, dass Martha die Mörderin ist, zu verzögern,</b> solltest du die Hinweise verknappen, wenn die SC Nachforschungen gegen sie anstellen:","sz":9.5,"box":[53.9,445.5,279.0,479.9],"p":26,"i":5,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"• Beantworte ihre Fragen nur teilweise, wenn sie einen Hinweis ausgeben.","sz":9.5,"box":[53.9,491.4,286.1,513.4],"p":26,"i":6,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"h","x":"SCHMERZEN HINTER DEN AUGEN","sz":14.0,"box":[70.9,552.8,222.9,566.8],"p":26,"i":7,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"Martha fühlt sich von Natur aus von negativen Emotionen angezogen. Wenn sie jemandes Schmerz spürt, erinnert sie sich daran und kann das später in einem Lied aufgreifen.","sz":9.0,"box":[70.9,579.3,260.4,624.3],"p":26,"i":8,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"Wenn ein SC <b>Nachforscht</b> und eine 7-9 erzielt, kannst du die betreffende Spieler:in nach dem Leid ihres Charakters fragen und festlegen, dass Martha darum weiß (durch ihre Spezialaktion <b>Schmerz hinter den Augen</b>). Dies ist eine gute Gelegenheit, Themen und Hintergrundgeschichte des Charakters ins Rampenlicht zu rücken.","sz":9.0,"box":[70.9,633.0,271.2,714.0],"p":26,"i":9,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"Zunächst wirkt Martha nett und verständnisvoll. Die Offenlegung des privaten Schmerzes markiert den SC für Marthas Aktion, die Totenklage.","sz":9.0,"box":[70.9,722.7,268.6,755.7],"p":26,"i":10,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"Marthas Bedrohungsprofil s. S. 38.","sz":9.0,"box":[70.9,764.3,208.8,773.3],"p":26,"i":11,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"• Wenn sie 7-9 würfeln, kannst du vage oder nur teils wahre Antworten geben, um die Wahrheit eine Weile zu verbergen. Prüft ein SC z. B., ob Martha lügt, kannst du sagen, dass das durch ihren Zustand oder Rausch schwer zu bestimmen ist oder sie sehr nervös zu sein scheint, was auf eine Lüge, oder den Stress der jüngsten Ereignisse zurückzuführen sein kann.","sz":9.5,"box":[309.0,59.9,540.8,144.4],"p":26,"i":12,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"<b>Wenn der Druck steigt und die SC Antworten verlangen, wird Martha falsche Informationen geben</b>, um das Vertrauen zu erhalten und eine Erklärung für ihr Verhalten liefern. Es folgen einige <b>teils wahre, teils falsche Hinweise</b>, die du nutzen kannst. Martha kann sie auch ohne <b>Nachforschungen</b> preisgeben.","sz":9.5,"box":[309.0,156.1,538.0,228.1],"p":26,"i":13,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"card","x":"<b>Um ihre Anwesenheit am Tatort zu entschuldigen</b>, kann Martha sich dem Team anvertrauen und ihre Kräfte offenbaren. Sie wird behaupten, den baldigen Tod einer Person spüren zu können und es ziehe sie zum Tatort, um das Opfer zu warnen.","sz":null,"k":"yellow","box":[309.3,240.5,541.7,322.0],"p":26,"i":14,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"card","x":"<b>Sie wird der Mörder:in ihre eigenen Methoden zuschreiben</b> (was technisch gesehen keine Lüge ist) und andeuten, dass sie glaubt, dass die Opfer vor Kummer sterben.","sz":null,"k":"yellow","box":[309.3,330.6,541.7,387.9],"p":26,"i":15,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"card","x":"<b>Martha könnte behaupten, dass es sich bei der Mörder:in um dieselbe Person handelt, die in der Vergangenheit ihren Auftritt sabotiert hat</b> (s. u.) und dass diese einen Groll gegen sie hegt, wodurch eine falsche Spur entsteht, die das Team verfolgen kann.","sz":null,"k":"yellow","box":[309.3,396.6,541.7,477.8],"p":26,"i":16,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"p","x":"Wenn man sich nach Martha oder ihren Hintergrund erkundigt, kann man einiges über ihre wechselhafte Geschichte erfahren:","sz":9.5,"box":[309.0,491.5,529.9,526.0],"p":26,"i":17,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"card","x":"Martha ist eine der besten Blues- und Jazzsängerinnen der Stadt. Sie war früher als „Die größte Soulstimme in Downtown“ bekannt.","sz":null,"k":"yellow","box":[309.3,536.3,541.7,581.8],"p":26,"i":18,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"card","x":"Nach einem Auftritt, bei dem das Publikum einen Nervenzusammenbruch erlitt und medizinische Hilfe brauchte, bezeichneten die Medien sie als „zu intensiv“, und ihre Karriere stockte. Sie behauptete öffentlich, der Vorfall sei ein Sabotageakt gegen ihre Karriere gewesen, bei dem jemand psychoaktive Drogen in die Getränke der Gäste gemischt habe.","sz":null,"k":"yellow","box":[309.3,590.4,541.7,695.8],"p":26,"i":19,"sec":"in-der-zwischenzeit-eine-vision-des-todes"},{"t":"card","x":"Danach begann sie zu trinken, wurde zur depressiven Exzentrikerin und trat nur noch in schäbigen und obskuren Clubs auf.","sz":null,"k":"yellow","box":[309.3,704.4,541.7,749.7],"p":26,"i":20,"sec":"in-der-zwischenzeit-eine-vision-des-todes"}],"size":[595.276,841.89]},"27":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 0:","sz":14.0,"box":[53.9,61.9,122.3,75.9],"p":27,"i":0,"skip":true,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"AUFHÄNGER","sz":23.0,"box":[53.9,84.2,170.2,107.2],"p":27,"i":1,"skip":true},{"t":"p","x":"So kannst du mit dem Team in den Fall starten:","sz":9.5,"box":[53.9,118.0,253.2,127.5],"p":27,"i":2,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Die Polizei</b> könnte das Team um Hilfe bitten, vor allem, wenn es früher schon mit den Behörden zusammengearbeitet hat oder eine Detektei betreibt. Die Beamten Das und Quinn haben gerade erst mit den Ermittlungen zu dem Vorfall im Bestattungsinstitut begonnen und sind ratlos: Sie haben drei scheinbar nicht miteinander verbundene verdächtige Todesfälle, bei denen ein Skinhead mit Kapuzenpulli eine Rolle spielt. Ihr Chef hält das für einen Zufall und hat ihnen 72 Stunden Zeit gegeben, um den Durchbruch zu erzielen, danach müssen sie den Fall abgeben. Sowohl Das, ein Riss, als auch Quinn, ein Schläfer, glauben, dass sie es mit einer Serienmörder:in zu tun haben, aber sie haben keine Ahnung von Motiv oder Methode. (Sie haben die letzten Todesfälle noch nicht mit dem Washboard in Verbindung gebracht, verdächtigen also Martha Ellis nicht im Geringsten). Um das Team zu rekrutieren, nimmt Officer Das telefonisch Kontakt auf oder taucht bei den SC auf. Sie berichtet Details und bittet um Hilfe, betont aber, dass die Mörder:in vor Gericht und die Angelegenheit auf legale Weise geklärt werden muss.","sz":9.5,"box":[53.9,138.5,286.3,400.0],"p":27,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• Der Besitzer des <u>Washboard,</u> <b>Sammy Jefferson Jr.</b> (Schläfer), kontaktiert vielleicht das Team, um Darnell Fox‘ Tod aufzuklären. Der alte Sammy ist von dem Todesfall in seinem Club wenig erschüttert, er befürchtet eher, die Glückssträhne seiner Sängerin zu unterbrechen. Er spürt, dass seine Diva seit dem Fall nervös ist, und will sicherstellen, dass ihr nichts passiert. Sammy, der Kontakt zu SC hat, die auf der falschen Seite des Gesetzes stehen, könnte das Team anheuern, um den Kerl mit dem Kapuzenpulli zu finden und dafür zu sorgen, dass er in seinem Club nicht noch einmal so eine Nummer abzieht. Sammy ist ein Mann mittleren Alters, der meist ein fleckiges Hemd, Hosenträger und eine Anzugshose trägt und den typischen Panamahut eines Jazzclub-Besitzers auf dem Kopf hat. Er ist ein gewiefter Geschäftsmann und spielt krasse Bluegrass-Melodien, wenn man ihm ein Banjo in die Hand drückt.","sz":9.5,"box":[53.9,408.2,286.2,621.7],"p":27,"i":4,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Eine Nebendarsteller:in könnte ein Opfer Ellis‘ werden.</b> Jemand, der einem der SC nahe steht, könnte die SC zu einem Auftritt Martha Ellis‘ einladen. Wähle eine Figur, die ein ausgeprägtes persönliches Trauma hat und leicht zu Ellis‘ nächstem Opfer werden könnte. Sie könnte am nächsten Morgen tot aufgefunden werden oder, wenn du dem Team eine Chance zur Rettung geben willst, an der SL-Szene <u>„Ein weiterer Mord“</u> (s. S. 38) beteiligt sein.","sz":9.5,"box":[53.9,629.8,286.3,735.3],"p":27,"i":5,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"SCHICHT 1:","sz":14.0,"box":[309.0,61.9,376.0,75.9],"p":27,"i":6,"skip":true,"sec":"schicht-1-trauer-um-die-vergangenheit"},{"t":"h","x":"TRAUER UM DIE VERGANGENHEIT","sz":23.0,"box":[309.0,84.2,470.9,138.1],"p":27,"i":7,"skip":true},{"t":"p","x":"Hier untersucht das Team die Tatorte der seltsamen Todesfälle. Zunächst scheint sie nichts zu verbinden, aber später wird klar, dass das Washboard und seine Sängerin, Martha Ellis, im Zentrum des Geschehens stehen.","sz":13.0,"box":[309.0,145.9,526.4,231.4],"p":27,"i":8,"sec":"schicht-1-trauer-um-die-vergangenheit"},{"t":"h","x":"DAS WASHBOARD","sz":16.0,"box":[334.8,250.0,450.3,266.0],"p":27,"i":9,"skip":true,"sec":"das-washboard"},{"t":"ro","x":"Versteckt im Keller eines schmutzigen braunen Steingebäudes, überschattet von den Wolkenkratzern der Innenstadt, könnte das Washboard nicht tiefer liegen, ohne in der Kanalisation zu enden. Der Laden wirkt herausgeputzt, als versuche er, die Gelegenheit für eine flüchtige Chance auf Ruhm zu nutzen. Die Eingangstür ist mit Plakaten beklebt, die Martha Ellis‘ nächsten Auftritt ankündigen.","sz":9.0,"box":[317.5,268.4,538.9,374.6],"p":27,"i":10,"sec":"das-washboard"},{"t":"p","x":"Das Washboard ist eine Institution, ein Jazz- und Blues-Club aus den Tagen, als die Stadt noch jung war. Im Gegensatz zu respektableren Pendants, die ihren Ruf über die Jahre aufbauten, war im Washboard immer ein wenig das falsche Publikum. Die großen Verbrecher blieben in eigenen Clubs und dem Washboard blieben die Gauner und Taugenichtse. Zunächst zog das Washboard auch Berufstätige aus der Mittelschicht an, die sich nach Besonderem sehnten und hier die Gesellschaft der raueren Stammkundschaft genossen. So lief das Geschäft für eine Weile gut. Aber die Trends wandelten sich, die Massen zogen weiter, so dass ein Besitzer nach dem anderen gezwungen war, das Lokal an den nächsten Hoffnungsvollen zu verkaufen.","sz":9.5,"box":[309.0,383.6,540.1,555.6],"p":27,"i":11,"sec":"das-washboard"},{"t":"p","x":"Der jetzige Besitzer, <b>Sammy Jefferson Jr</b>., zog vor Jahrzehnten aus den Vorstädten hierher. Er versuchte sich an allem, was man auf der Straße tun kann, liebte aber immer schon Musik. Als sich die Gelegenheit ergab, kaufte er den Club. Sammy wusste nur zu gut, dass er, um den Laden am Laufen zu halten, in dem Hinterzimmer andere Dinge machen musste, doch sein Traum war es, es als Clubbesitzer wirklich zu schaffen.","sz":9.5,"box":[309.0,564.2,540.3,661.2],"p":27,"i":12,"sec":"das-washboard"},{"t":"p","x":"Im Washboard finden bis zu 200 Gäste Platz. Das Rotlicht sorgt für die richtige Stimmung, verleiht dem Ort aber ein dunkles, schäbiges Flair. Zwei lange Bars säumen den Hauptraum, etwa 20 kleine runde Tische sind vor der mittelgroßen Bühne verteilt. Im hinteren Teil ist die Küche, eine Garderobe, der Abstellraum und Sammys Büro. Eine Hintertür führt in eine schmutzige Seitengasse, enger als die, die zur Vordertür führt.","sz":9.5,"box":[309.0,669.9,541.4,766.9],"p":27,"i":13,"sec":"das-washboard"}],"size":[595.276,841.89]},"28":{"tab":"","blocks":[{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER DARNELL FOX‘ TOD</b>","sz":9.5,"box":[54.2,62.6,194.7,84.6],"p":28,"i":0,"sec":"das-washboard"},{"t":"card","x":"<b>Der Gerichtsmediziner schreibt</b>, Darnell Fox sei an unerklärlichem Herzversagen gestorben.","sz":null,"k":"yellow","box":[54.1,93.9,286.6,127.6],"p":28,"i":1,"sec":"das-washboard"},{"t":"card","x":"<b>Alle im Washboard erzählen die gleiche Geschichte:</b> Martha und Syrus, der Türsteher, haben den Streit zwischen Darnell und dem Killer mitbekommen. Sie sahen, wie Darnell zusammenbrach und der Mörder floh. (Das ist eine Lüge, aber alle Stammgäste glauben Martha und Syrus.)","sz":null,"k":"yellow","box":[54.1,136.8,286.6,233.3],"p":28,"i":2,"sec":"das-washboard"},{"t":"card","x":"<b>Der mutmaßliche Killer</b> muss das Schloss an der Hintertür mit einem Brecheisen aufgestemmt haben, während Syrus, der Türsteher, den Eingang abschloss.","sz":null,"k":"yellow","box":[54.1,242.2,286.6,301.2],"p":28,"i":3,"sec":"das-washboard"},{"t":"card","x":"Eine <b>Befragung Syrus‘</b> könnte ergeben, dass Martha bereits da war, als er ankam. Sammy gab ihm einen Bonus, damit er das Gegenteil behauptete, um sie aus der Sache rauszuhalten.","sz":null,"k":"yellow","box":[54.1,310.5,286.6,369.2],"p":28,"i":4,"sec":"das-washboard"},{"t":"card","x":"<b>Mit dieser Tatsache konfrontiert würde Martha sagen, Darnell habe sie nach der Show abgepasst</b> und ihr seine Liebe gestanden. Es sei normal, dass sich ein Fan in eine Künstlerin verliebt, weswegen sie ihn höflich habe abblitzen lassen. Aber dann sei der Mörder gekommen und Darnell zusammengebrochen.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,150.6],"p":28,"i":5,"sec":"das-washboard"},{"t":"card","x":"<b>Niemand im Washboard kannte Darnell oder seine Freund:innen.</b> Als Sammy und Syrus sich umhörten, erfuhren sie, dass es sich um eine Gruppe junger Berufstätiger handelte, die ein Lokal für ein Doppeldate suchten.","sz":null,"k":"yellow","box":[309.3,159.6,541.7,231.0],"p":28,"i":6,"sec":"das-washboard"},{"t":"card","x":"<b>Darnells Freund:innen sind leicht zu finden.</b> Sie stehen unter Schock und führen seinen Tod auf ein unerkanntes Herzleiden zurück. Sie erzählen von einem schüchternen und sanftmütigen Mann, der nie erwähnt hat, dass er Hilfe braucht. Unter vier Augen verraten die Damen, dass er sehr einsam schien. Sie alle arbeiten für eine lokale Werbeagentur.","sz":null,"k":"yellow","box":[309.3,240.2,541.7,349.1],"p":28,"i":7,"sec":"das-washboard"}],"size":[595.276,841.89]},"29":{"tab":"","blocks":[{"t":"card","x":"<b>Jenseits des Nebels</b> ist der Ort ein düsterer Sumpf voller Tristesse und alles durchdringender Einsamkeit, emotional und symbolisch, mit schlammigem, nebeligen Boden. Eine Tin Whistle spielt eine traurige Melodie. Wenn ein SC mit Darnells Geist Kontakt aufnimmt, ist er <t>von Trauer überwältigt 4</t> und glaubt, er sei gestorben, weil er einfach nicht mehr konnte.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,163.0],"p":29,"i":0,"sec":"das-washboard"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER DAS WASHBOARD</b>","sz":9.5,"box":[54.2,178.8,218.2,200.8],"p":29,"i":1,"sec":"das-washboard"},{"t":"card","x":"<b>Sammy Jefferson nutzt diesen Ort für mehr als Musik:</b> Etwas Schmuggel, illegales Glücksspiel, manchmal Hehlerei mit geringem Risiko, mehr nicht. Er ist bereit, das Team zu bezahlen, damit es dicht hält, oder Syrus dafür, dass er die Schnüffler:innen zum Schweigen zwingt.","sz":null,"k":"yellow","box":[54.1,210.5,286.6,294.3],"p":29,"i":2,"sec":"das-washboard"},{"t":"card","x":"<b>Sammy setzt alles auf Martha Ellis‘ Erfolg, in der Hoffnung, dass er so den Sprung in die Legalität schafft</b> und seine dubiosen Hinterzimmeraktivitäten lassen kann. Er scheint zu vielem bereit, um die Sängerin – oder ihren Gesang – vor Schaden zu bewahren.","sz":null,"k":"yellow","box":[54.1,303.3,286.6,387.4],"p":29,"i":3,"sec":"das-washboard"},{"t":"card","x":"<b>Ein Stammgast des Washboard</b> hat von einem anderen Gast gehört, der an einem Herzinfarkt gestorben ist, und weist das Team auf das <u>Bancroft-Penthouse</u> hin. Eine andere Person sagt, die Sängerin Martha sei vor nicht einmal zwei Tagen in ein Drama im <u>Bestattungsinstitut Green Meadows</u> verwickelt gewesen.","sz":null,"k":"yellow","box":[54.1,396.3,286.6,492.8],"p":29,"i":4,"sec":"das-washboard"},{"t":"threat","stars":"★","name":"SAMMY JEFFERSON JR.","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 1 / GEIST BRECHEN 3","items":["<b>Durchtrieben</b>: Wenn man Sammy befragte, nimmt er zuerst <t>durchtrieben 2</t>.","<b>Dem Sturm trotzen</b>: Wenn Sammy ein Angebot macht, legt die SL als Belohnung einen temporären Geschichten-Markers fest. Wer die Bestechung annimmt, erhält diesen.","<b>Buch führen</b>: Wenn Sammy sich gegen jemanden wendet, verleiht er <t>verwickelt</t> mit 1 Stufe pro Marker, den die Person bei Dem Sturm trotzen akzeptiert hast. Sie kann <b>Sich der Gefahr stellen</b>.","<b>Situation entschärfen</b>: Wenn Sammy ein Banjo spielt, werden die Zuhörenden ruhig. Als Aktion kann die SL: einen emotionalen Zustand um 1 vermindern, eine emotionale Stärke verbrennen oder <t>gechillt 1</t> verleihen.","Jemanden mit einer Pistole oder Brecheisen bedrohen (<t>bedroht 2</t>) oder seine Drohungen wahr machen (<t>Fleischwunde 2</t> oder <t>zusammengeschlagen 2</t>)","Jemandem helfen, sich zu entspannen (einen emotionalen Zustand 1 vermindern, eine emotionale Stärke verbrennen oder <t>gechillt 1</t> verleihen)","Jemanden lächelnd und mit offenen Armen begrüßen","Vorschlagen, woanders ungestört über das Geschäftliche zu sprechen","Der Band sagen, sie soll sofort anfangen zu spielen"],"box":[438.7,58.2,448.9,70.2],"p":29,"i":5,"sec":"das-washboard"},{"t":"threat","stars":"★","name":"SYRUS, DER TÜRSTEHER","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 2 / BE- STECHEN 2","items":["<b>Nicht in meiner Schicht</b>: Wenn Syrus die Szene betritt, gib ihm <t>aufmerksam 2</t>.","<b>Boxer</b>: Wenn man Syrus im Nahkampf mit Schlägen oder Waffen angreift, wird die Stufe des resultierenden Zustands um 1 reduziert.","Jemanden schlagen (<t>desorientiert 2</t>) oder in den Schwitzkasten nehmen (Gefesselt 3)","Eine desorientierte oder gepackte Person rauswerfen (<t>gedemütigt 2</t>)","Über seine verschränkten Arme auf jemanden herabschauen"],"box":[441.0,500.4,451.2,512.4],"desc":"Syrus ist seit ein paar Monaten Türsteher im Washboard. Er ist ein typischer Muskelprotz, der mit 1,90 m die meisten Gäste überragt und Arme wie Baumstämme und einen Brustkasten wie ein Fass hat. Glatze, ein enges schwarzes T-Shirt und der dünne Schnurrbart lassen ihn cool, aber gefährlich wirken.","p":29,"i":6,"sec":"das-washboard"}],"size":[595.276,841.89]},"30":{"tab":"","blocks":[{"t":"h","x":"DAS &amp; QUINN","sz":15.0,"box":[53.9,62.1,142.7,77.1],"p":30,"i":0,"sec":"das-washboard"},{"t":"p","x":"Ganz gleich, ob sie um Hilfe gebeten haben oder einfach nur an den Tatorten nach Antworten suchen, die Beamt:innen Chaavi Das und Matt Quinn finden immer einen Weg, ihre Nase in die Angelegenheiten des Teams zu stecken.","sz":9.5,"box":[53.9,82.8,276.5,142.3],"p":30,"i":1,"sec":"das-washboard"},{"t":"p","x":"Dieses engagierte, dynamische Duo macht alles, was in der gesamten Stadt passiert, zu seiner Sache. Das ist eine temperamentvolle, geradlinige Polizistin, die klein, aber oho ist. Als berührter Riss Gramadevatas, des Schutzgeistes einer Stadt, verfügt sie – neben ihrem Taser und ihrer Pistole – über die typischen Kräfte einer Schutzgottheit. Sie kann magische Schilde erschaffen, die Menschen und Dinge vor physischem und magischem Schaden bewahren.","sz":9.5,"box":[53.9,151.0,284.9,260.5],"p":30,"i":2,"sec":"das-washboard"},{"t":"p","x":"Officer Quinn – ein großer, gut aussehender, gut genährter Kerl – ist ein großer Teddybär, der es vorzieht, Gewalt zu vermeiden (bis die Pflicht ruft, dann ist er ein fähiger Kämpfer). Er ist ein Schläfer, aber einer von der Sorte, die alle Verschwörungstheorien glauben, nur","sz":9.5,"box":[53.9,269.1,285.0,328.6],"p":30,"i":3,"sec":"das-washboard"},{"t":"p","x":"<b>DAS &amp; QUINN</b>","sz":12.0,"box":[64.8,380.4,144.4,392.4],"p":30,"i":4,"sec":"das-washboard"},{"t":"p","x":"<i>Verbündete</i>","sz":10.0,"box":[64.8,402.2,119.1,412.2],"p":30,"i":5,"sec":"das-washboard"},{"t":"h","x":"IDENTITÄT","sz":10.0,"box":[64.8,423.6,111.1,433.6],"p":30,"i":6,"sec":"das-washboard"},{"t":"p","x":"Es ist unsere Aufgabe, die Straßen der Innenstadt sicher zu halten.","sz":9.0,"box":[64.8,438.4,261.0,459.4],"p":30,"i":7,"sec":"das-washboard"},{"t":"h","x":"STÄRKEN","sz":10.0,"box":[64.8,471.1,105.4,481.1],"p":30,"i":8,"sec":"das-washboard"},{"t":"card","x":"<i>Streife</i>, <i>Polizeiarbeit</i>, <i>Das Böse vertreiben</i>, <i>Sich der Arbeit widmen</i>, <i>Muskeln und Verstand kombinieren</i>, <i>Magischer Schild</i>, <i>Zeugenbefragung</i>, <i>Zugang zu Polizeiakten</i>, <i>Die üblichen Verdächtigen</i>, <i>Herz aus Gold</i>","sz":null,"k":"yellow","box":[65.1,484.7,277.9,530.8],"p":30,"i":9,"sec":"das-washboard"},{"t":"h","x":"SCHWÄCHEN","sz":10.0,"box":[64.8,542.7,121.7,552.7],"p":30,"i":10,"sec":"das-washboard"},{"t":"card","x":"<i>Müssen JEDE illegale Aktivität melden</i>, <i>Das ist eine ungestüme Gewalt</i>, <i>Quinn ist ein großer Softie</i>, <i>Ärger mit dem Chef</i>","sz":null,"k":"yellow","box":[65.1,556.1,266.4,590.4],"p":30,"i":11,"sec":"das-washboard"},{"t":"h","x":"THEMENVERBESSERUNG","sz":10.0,"box":[64.8,602.2,171.5,612.2],"p":30,"i":12,"sec":"das-washboard"},{"t":"p","x":"<b>Aufopferung:</b> Wenn du einen Erfolg bei <b>Sich der Gefahr stellen</b> erzielst, kannst du dich immer entscheiden, das Ergebnis auf eine Person oder ein Objekt in deiner Umgebung auszudehnen, die du schützen kannst, auch wenn du dir dafür eine Blöße gibst. Bei 10+ erleiden sie keinen Zustand, du erleidest den Zustand mit -1 Stufe. Bei 7-9 erhalten sie den Zustand mit -1 Stufe und du den vollen. Wenn die Aktion Mega! ist, kannst du bei 12+ wählen, euch beide vollständig zu schützen (statt eine der anderen 12+ Optionen).","sz":9.0,"box":[64.8,616.9,274.9,745.9],"p":30,"i":13,"sec":"das-washboard"},{"t":"p","x":"nie auf sie eingeht. Er folgt Das durch Dick und Dünn, auch wenn er oft nicht sieht, was sie sieht. Er sagt, er wünschte, er könnte durch ihre Augen sehen, aber das kann er nicht, und so kann er ruhig schlafen.","sz":9.5,"box":[309.0,59.9,536.7,106.9],"p":30,"i":14,"sec":"das-washboard"},{"t":"p","x":"Die beiden können als Verstärkungs- oder Unterstützungs-NSC dienen, die helfen, Tipps geben und das Team durch den Fall, die Ebene oder die Kampagne führen. Sie können als Nervensägen dienen, indem sie immer dann auftauchen, wenn es für die illegalen Machenschaften des Teams am misslichsten ist. Wenn sie vorübergehend oder dauerhaft Verbündete werden, kannst du sie durch ein zusätzliches Thema darstellen.","sz":9.5,"box":[309.0,115.6,539.8,212.6],"p":30,"i":15,"sec":"das-washboard"},{"t":"threat","stars":"★★★","name":"DAS & QUINN /","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / KORRUMPIEREN 5 / ÜBER IHRE AUTORITÄT HIN- WEGSETZEN 3","items":["<b>Kombinationsgabe:</b> Wenn Das oder Quinn den Schauplatz zum ersten Mal besichtigen, wird die SL dir eine Frage stellen. Du musst mit einer direkten Antwort oder einem belastbaren Hinweis antworten. Die Polizist:in kennt deine Antwort, auch wenn dein Charakter sie nicht ausgesprochen hat.","<b>Am Ball:</b> Wenn Das oder Quinn die Szene betreten, gib ihnen <t>aufmerksam 1</t>.","<b>Schutz vor Bösem (nur Das):</b> Wenn Officer Das einen Zustand aus einer Quelle erhält, die von Natur aus böse oder dunkel ist, sinkt dessen Stufe um 2.","Jemanden in die Enge treiben (die Wahrheit sagen oder <t>unter Druck 2</t> nehmen)","Mit einer Schusswaffe (<t>Schusswunde 3</t>) oder einem Taser (<t>betäubt 3</t>) auf Verdächtige schießen oder sie damit bedrohen","Verdächtigen Handschellen anlegen oder diese enger machen (<t>Handschellen 2</t>)","(Nur Das) Jemanden segnen oder bezaubern, um ihn vor Schaden zu bewahren (<t>geschützt 2</t>)","(Nur Das) Die Mächte des Bösen oder der Dunkelheit bannen (<t>verbannen 3</t>)","Eine Szene beobachten und miteinander besprechen","Ein Beweisstück finden","Wenn sie allein sind: Verstärkung anfordern"],"box":[387.9,270.1,424.6,282.1],"desc":"Obwohl beide Streifenpolizist:innen sind, verwenden sowohl Das als auch Quinn das Bedrohungsprofil Detective (s. S. 287), um ihre polizeilichen Fähigkeiten zu reflektieren. Das verfügt über das Mythos-Kräfteset Sendbote des Lichts (s. S. 290).","p":30,"i":16,"sec":"das-washboard"}],"size":[595.276,841.89]},"31":{"tab":"","blocks":[{"t":"h","x":"DAS BANCROFT-PENTHOUSE","sz":16.0,"box":[79.7,68.9,265.7,84.9],"p":31,"i":0,"skip":true,"sec":"das-bancroft-penthouse"},{"t":"ro","x":"Das Penthouse der Bancrofts ist mit den besten und trendigsten Einrichtungsgegenständen ausgestattet, die man für Geld kaufen kann. Jeder Winkel demonstriert Geld und Macht. Wenn man den spiegelnden Marmorboden betritt, sieht man, dass das alles nur ein Vorgeschmack war: Die Eigentumswohnung bietet einen Panoramablick auf die Dächer der Stadt. Atemberaubend, aber Junge, fühlt sich das leer an!","sz":9.0,"box":[62.4,87.3,283.8,193.5],"p":31,"i":1,"sec":"das-bancroft-penthouse"},{"t":"p","x":"<b>Tiffany Bancroft</b> war Martha Ellis‘ zweites Opfer. Sie war eine schöne Frau Ende 30, die überall auffiel, wo sie hinging, und das Washboard bildete keine Ausnahme. Martha bemerkte sie, als sie mit ihrem Mann <b>Ross Bancroft</b> hereinkam, von dem sie erfuhr, dass er hochrangige Führungskraft bei einem Hedgefonds in der Innenstadt war. Obwohl das Paar glamourös wirkte, spürte Martha Traurigkeit in Tiffany. Sie traf sie auf der Damentoilette und lud sie zu einer Zigarette und einem Drink in ihre Garderobe ein. Als Tiffany ihr von ihrer lieblosen Ehe und ihrer unerfüllten Existenz erzählte, erkannte Martha, dass die Frau sich in ihrem perfekten Leben gefangen fühlte. Sie wollte helfen, also tauschten sie Handynummern aus und vereinbarten ein Treffen in der folgenden Woche.","sz":9.5,"box":[53.9,202.5,286.3,387.0],"p":31,"i":2,"sec":"das-bancroft-penthouse"},{"t":"p","x":"Martha besuchte das Penthouse der Bancrofts, und als sich die Gelegenheit bot, setzte sie sich nach vielen Gesprächen und noch mehr Wein an den Flügel und sang ihre Gastgeberin zu Tode. Nowak tauchte rechtzeitig auf, um Zeuge zu werden, den Sicherheitsdienst des Gebäudes bereits auf den Fersen. Als er merkte, dass er zu spät gekommen war, floh er. Martha hörte, dass den ankommenden Sicherheitsdienst und nutzte die Gelegenheit, um ungesehen über die Feuertreppe zu verschwinden. Als die Polizei eintraf, kümmerte sie sich um Nowak, den mutmaßlichen Täter, und das Opfer, aber niemand dachte daran, nach Ellis zu suchen.","sz":9.5,"box":[53.9,395.6,283.3,542.6],"p":31,"i":3,"sec":"das-bancroft-penthouse"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER TIFFANY BANCROFTS TOD</b>","sz":9.5,"box":[54.2,551.4,194.7,573.4],"p":31,"i":4,"sec":"das-bancroft-penthouse"},{"t":"card","x":"<b>Nach Angaben des Sicherheitschefs</b> hat ein Skinhead im Hoodie, etwa 25 bis 30 Jahre alt, das Wachpersonal ausgetrickst und es zu den Aufzügen geschafft. Er fuhr zum Penthouse der Bancrofts und erschreckte Tiffany zu Tode. Dann entkam er knapp, indem er durch ein Fenster sprang, ehe man ihn festnehmen konnte.","sz":null,"k":"yellow","box":[54.1,580.0,286.6,685.4],"p":31,"i":5,"sec":"das-bancroft-penthouse"},{"t":"card","x":"<b>Laut Gerichtsmedizin ist</b> Tiffany Bancroft an unerklärlichem Herzversagen gestorben.","sz":null,"k":"yellow","box":[54.1,694.1,286.6,727.2],"p":31,"i":6,"sec":"das-bancroft-penthouse"},{"t":"card","x":"<b>Dehnt man die Nachforschungen aus,</b> könnten die Überwachungskameras oder der Portiers offenbaren, dass Martha Ellis zu Besuch kam, etwa drei Stunden, bevor der Eindringling auftauchte. Niemand hat sie das Haus","sz":null,"k":"yellow","box":[54.1,735.8,286.6,817.3],"p":31,"i":7,"sec":"das-bancroft-penthouse"},{"t":"card","x":"<b>Die Nachbarn hörten Klaviermusik,</b> bevor Tiffany starb, aber Bancroft betont, dass das Stück aus der Konserve gekommen sein muss, da weder er noch seine Frau spielen konnten.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,111.5],"p":31,"i":8,"sec":"das-bancroft-penthouse"},{"t":"card","x":"Es liegt ein Ticket für Martha Ellis‘ Auftritt im <u>Washboard</u> nächste Woche auf dem Flügel.","sz":null,"k":"yellow","box":[309.3,120.1,541.7,153.5],"p":31,"i":9,"sec":"das-bancroft-penthouse"},{"t":"card","x":"Jemand (Martha) hat etwa zum Zeitpunkt von Tiffanys Tod vom Penthouse aus <u>Greifers</u> Nummer angerufen.","sz":null,"k":"yellow","box":[309.3,162.1,541.7,207.4],"p":31,"i":10,"sec":"das-bancroft-penthouse"},{"t":"card","x":"<b>Jenseits des Nebels</b> scheint das Penthouse von demselben Sumpf bedeckt zu sein wie das Washboard, wenn auch mit knorrigen Bäumen, die das Gefühl längst erloschener Hoffnungen und Träume und einer alles beherrschenden Leere vermitteln. Wenn ein SC mit Tiffanys Geist in Kontakt treten kann, ist sie <t>verbittert und wütend 3</t> und will nicht reden, da sie glaubt, gestorben zu sein, weil sie endlich erkannt hatte, dass es ihr einziger Ausweg war.","sz":null,"k":"yellow","box":[309.3,216.3,541.7,345.6],"p":31,"i":11,"sec":"das-bancroft-penthouse"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER ROSS BANCROFT</b>","sz":9.5,"box":[309.4,358.1,449.8,380.1],"p":31,"i":12,"sec":"das-bancroft-penthouse"},{"t":"p","x":"Ross Bancroft, der Gatte der Verstorbenen, ist ein kaltherziger Hedgefonds-Manager, der durch die Ermordung seiner Frau aus der erdrückenden Ehe ausbrechen und seine Zukunft sichern wollte. Das ist ein Ablenkungsmanöver, denn er konnte seine Pläne nie umsetzen und ist nicht der Mörder. Aus Angst, dass eine Untersuchung seinen früheren Plan aufdecken könnte, ist er <t>unkooperativ 2</t> und möchte, dass die Ermittlungen so schnell wie möglich einstellt werden.","sz":9.5,"box":[309.0,388.7,538.3,498.2],"p":31,"i":13,"sec":"das-bancroft-penthouse"},{"t":"card","x":"<b>Ross Bancroft behält seine normalen Gewohnheiten bei</b>, arbeitet bis spät in die Nacht im Büro seines Hedgefonds und trinkt abends in seiner Wohnung Whiskey. Er scheint nicht so traurig zu sein, wie man erwarten würde.","sz":null,"k":"yellow","box":[309.3,504.3,541.7,575.4],"p":31,"i":14,"sec":"das-bancroft-penthouse"},{"t":"card","x":"<b>Wenn man ihn nach dem Grund für den Tod seiner Frau fragt,</b> sagte er lapidar, sie sei so sehr an ihre Scheinwelt, in der Perfektion herrschte, gewöhnt, dass sie der Einbrecher so erschreckte, dass ihr Herz stehenblieb.","sz":null,"k":"yellow","box":[309.3,584.6,541.7,656.1],"p":31,"i":15,"sec":"das-bancroft-penthouse"},{"t":"card","x":"<b>Bancroft hatte vor, ein teures Gift zu verwenden, das einen Herzinfarkt simuliert</b>. Als Tiffany starb, warf er das Fläschchen ins Klo, aber es blieb im Rohrsystem des Gebäudes hängen. Eine einfache Blutuntersuchung kann das Gift nicht nachweisen, aber Mythos-Kräfte oder eingehendere Laboruntersuchungen würden zeigen, dass Tiffany es nicht im Körper hatte. Dafür müsste das Team die Leichenhalle aufsuchen.","sz":null,"k":"yellow","box":[309.3,665.3,541.7,798.9],"p":31,"i":16,"sec":"das-bancroft-penthouse"}],"size":[595.276,841.89]},"32":{"tab":"","blocks":[{"t":"p","x":"Wenn das Team zu viel herumschnüffelt, könnte Bancroft sein wahres Gesicht zeigen und jemanden anheuern, um sie loszuwerden. Ross kann sich jeden leisten, besonders alte Feinde oder die Nemesis eines SC, die für Geld arbeiten. Ansonsten sind die paramilitärischen Söldner der Walhalla Boys (Warägergarde, eine Eliteeinheit nordischer Krieger, die als Leibwache des byzantinischen Kaisers diente) seine Ansprechpartner für diese Art Arbeit. Die <b>Walhalla Boys</b> sollen dafür zu sorgen, dass das Team Tiffanys Tod nicht untersucht.","sz":9.5,"box":[53.9,59.9,285.4,181.9],"p":32,"i":0,"sec":"das-bancroft-penthouse"},{"t":"threat","stars":"★★★","name":"WALHALLA BOYS","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / BESTECHEN 4 / BEDROHEN 5","items":["<b>Kollektiv:</b> Dieses Kollektiv hat wenige Mitglieder und daher einen Größenfaktor von 1.","<b>Paramilitärische Ausbildung:</b> Wenn die Walhalla Boys den Schauplatz betreten, gib ihnen <i>Schutzwesten</i> und <t>aufmerksam 2</t>.","<b>Berserker:</b> Wenn sie einen Zustand physischen Schadens oder der Überwältigung erleiden, kann die SL ihnen den Zustand <t>Berserker 2</t> geben, wenn <i>Verletzen oder unschädlich machen</i> nicht ausgeschöpft ist. Dieser Zustand gilt sowohl für Angriffe, die auf die Berserker abzielen (einschließlich mentaler Angriffe), als auch, wenn sie <b>Sich der Gefahr stellen</b> gegen Angriffe.","Sich gegenseitig mit Gesten oder knappen Lauten Signale geben und dann eine taktische Routine ausführen (sich einen <t>taktischen Vorteil 2</t> verschaffen oder bis zu zwei Stufen negativer taktischer Zustände entfernen)","Ein Ziel mit Sperrfeuer eindecken(<t>in die Enge getrieben 3</t>) oder mit aggressiver Feuerkraft attackieren (<t>Schusswunde 3</t> oder <t>blutende Wunde 3</t>)","Dem besiegten Feind eine Nachricht von ihrem Auftraggeber übermitteln (den Zustand <t>eingeschüchtert</t> mit einer Stufe, die der des Schadens oder Überwältigungszustands des Ziels entspricht, verleihen)","Aufstellung in einer Sternformation, Rücken an Rücken, die ihre Ausbildung verrät"],"box":[148.1,212.1,178.7,224.1],"desc":"Die Walhalla Boys sind gewöhnliche Söldner, die meist in einer Mischung aus Uniformteilen und Leder gekleidet sind, die Funktionalität und Einschüchterung perfekt verbindet. Taktisch geschult und kampferprobt, durch den Mythos und ihr alltägliches Training, sind sie in der Lage, die meisten schwachen bis mittelstarken Riss-Teams auszuschalten. Die Walhalla Boys verfügen über Schrotflinten, Armbrüste, Wurfäxte und Granaten.","p":32,"i":1,"sec":"das-bancroft-penthouse"},{"t":"h","x":"BESTATTUNGSINSTITUT GREEN MEADOWS","sz":16.0,"box":[333.9,68.9,495.5,101.9],"p":32,"i":2,"skip":true,"sec":"bestattungsinstitut-green-meadows"},{"t":"ro","x":"Am Knauf der Eingangstür dieses totenstillen Bestattungsunternehmens in der Vorstadt hängt ein Schild mit der Aufschrift GESCHLOSSEN. Die Tür steht einen Spalt offen und man hört, wie jemand im Inneren arbeitet. Das alte Haus scheint zu knarren und zu flüstern, wenn man eintritt. Drinnen liegt ein Porträt des letzten Verstorbenen, eines Teenagers, auf dem Boden des Foyers. Anscheinend hat hier ein Kampf stattgefunden. Die Glasscherben des zerbrochenen Bilderrahmens hat noch niemand aufgekehrt.","sz":9.0,"box":[317.5,104.3,538.9,242.9],"p":32,"i":3,"sec":"bestattungsinstitut-green-meadows"},{"t":"p","x":"<b>Adam Walsh</b> war das dritte und jüngste Opfer Martha Ellis‘. Als alleinerziehender Vater von drei Kindern, der vor kurzem sein fünfzehnjähriges Kind (Teddy) durch eine Krankheit verloren hatte, ertrank Adam in Verzweiflung. Martha, die auf Teddys Beerdigung sang und die tiefe Dunkelheit in ihm spürte, fühlte sich fast wie seine Retterin, als sie die Todesfee in sich wachrief und über seine unendliche Traurigkeit sang.","sz":9.5,"box":[309.0,251.9,541.4,348.9],"p":32,"i":4,"sec":"bestattungsinstitut-green-meadows"},{"t":"p","x":"Nowak tauchte uneingeladen bei der Beerdigung auf, stürmte durch die Tür und verursachte einen Tumult, so dass alle sahen, wie er mit Adam Walsh überraschte Blicke austauschte. Walsh, der den Mann nicht erkannte, spürte plötzlich einen stechenden Schmerz in der Brust und eilte in die Herrentoilette, wo er zusammenbrach und die letzten Töne des Liedes, das ihn getötet hatte, aus der Trauerhalle hörte.","sz":9.5,"box":[309.0,357.5,540.7,454.5],"p":32,"i":5,"sec":"bestattungsinstitut-green-meadows"},{"t":"p","x":"Diesmal stand Martha ihrem unheimlichen Verfolger Auge in Auge gegenüber, und da sie wusste, dass sie ihm nicht entkommen konnte, rief sie: „Das ist der Mörder“, was die Menge veranlasste, Nowak zu umringen und hinauszudrängen. Martha eilte zu ihrem Auto und fuhr davon. Nowak entkam nur knapp mit blauen Flecken und gebrochenen Rippen.","sz":9.5,"box":[309.0,463.2,538.3,547.7],"p":32,"i":6,"sec":"bestattungsinstitut-green-meadows"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER ADAM WALSHS TOD</b>","sz":9.5,"box":[309.4,556.5,449.8,578.5],"p":32,"i":7,"sec":"bestattungsinstitut-green-meadows"},{"t":"card","x":"<b>Adam Walsh</b> trauerte um seinen Sohn Teddy, der an einer unheilbaren Krankheit gestorben war. Die Mutter hatte die Familie vor Jahren verloren. Adam hat noch zwei Töchter, die jetzt bei Verwandten leben, zumindest bis zum Abschluss der Ermittlungen.","sz":null,"k":"yellow","box":[309.3,586.4,541.7,670.2],"p":32,"i":8,"sec":"bestattungsinstitut-green-meadows"},{"t":"card","x":"<b>Die Trauergäste</b> haben beobachtet, wie er sich an die Brust fasste, als er den Eindringling im Kapuzenpulli sah. Dann rief die Sängerin: „Das ist der Mörder!“, und die Anwesenden verfolgten ihn, teils handgreiflich, aber er entkam. Kurz darauf fand man Adam Walsh tot im WC.","sz":null,"k":"yellow","box":[309.3,679.4,541.7,763.2],"p":32,"i":9,"sec":"bestattungsinstitut-green-meadows"}],"size":[595.276,841.89]},"33":{"tab":"","blocks":[{"t":"card","x":"<b>Die Besitzerin</b> des Bestattungsinstituts Green Meadow, <b>Sylvia Martinez</b> (Schläferin), war diejenige, die Martha Ellis eingeladen hatte, bei der Beerdigung zu singen. Sie tat damit ihrem Freund Sammy, Besitzer des <u>Washboard</u> und Manager von Martha Ellis, einen Gefallen.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,138.0],"p":33,"i":0,"sec":"bestattungsinstitut-green-meadows"},{"t":"card","x":"<b>Die Gerichtsmedizin schreibt</b>, Adam Walsh starb an unerklärlichem Herzversagen.","sz":null,"k":"yellow","box":[54.1,147.2,286.6,180.9],"p":33,"i":1,"sec":"bestattungsinstitut-green-meadows"},{"t":"card","x":"<b>Alle, die ihn kannten, wissen,</b> dass Walsh vom Tod seines Sohnes zutiefst erschüttert war.","sz":null,"k":"yellow","box":[54.1,190.1,286.6,224.1],"p":33,"i":2,"sec":"bestattungsinstitut-green-meadows"},{"t":"card","x":"<b>Aufmerksame Beobachter</b> beschreiben, dass der Eindringling nach Maschinenöl und Chemikalien roch. Die Untersuchung der Stelle, an der die Trauergäste ihn zu Boden rangen, die Entnahme chemischer Proben aus einem zerrissenen Stück seines Kapuzenpullovers und/ oder die Verfolgung seiner Spur mit anderen weltlichen oder mythischen Mitteln könnten zur <u>Schweißerei Harrington</u> führen.","sz":null,"k":"yellow","box":[54.1,233.3,286.6,354.5],"p":33,"i":3,"sec":"bestattungsinstitut-green-meadows"},{"t":"card","x":"<b>Jenseits des Nebels</b> ist das Bestattungsinstitut eine Ansammlung von Geistern Verstorbener (<t>laut und wütend 3</t>), und es ist schwer, wenn nicht unmöglich, den Geist Adam Walshs zu finden, der immer noch den seines Sohnes umarmt und in einer dunklen Ecke weint. Alle Geister würden sagen, dass sie den Tod selbst gesehen haben, als er heute das Beerdigungsinstitut besuchte (Nowak, Geist der zukünftigen Weihnacht) und dass sie seine Ankündigung gehört haben (Ellis, die Banshee). Es gibt Spuren desselben Sumpfes wie im Washboard und im Bancroft-Penthouse, aber er ist mit den Verstorbenenaktivitäten vermischt.","sz":null,"k":"yellow","box":[54.1,363.7,286.6,547.5],"p":33,"i":4,"sec":"bestattungsinstitut-green-meadows"},{"t":"h","x":"ANGRIFF AUF MARTHA","sz":16.0,"box":[78.0,581.5,226.1,597.5],"p":33,"i":5,"skip":true,"sec":"angriff-auf-martha"},{"t":"ro","x":"Das plötzliche Klingeln deines Telefons schreckt dich auf. Es ist Officer Chaavi Das. „Der Killer hat sie erwischt. Martha Ellis. Sie hat es irgendwie überlebt, ist aber übel zugerichtet. Ihr kommt besser her.„","sz":9.0,"box":[62.4,599.9,283.8,662.9],"p":33,"i":6,"sec":"angriff-auf-martha"},{"t":"p","x":"Früher oder später findet Nowak Martha und versucht, sie vor ihrer Zukunft zu warnen. Dies geschieht zwischen den Szenen, ohne das Teams, wahrscheinlich im <u>Washboard</u> oder in ihrer Wohnung. Leider handelt Nowak nicht sehr durchdacht. Er versucht zu kommunizieren, kann aber seine Botschaft nicht vermitteln (er ist nicht nur stumm, sondern annähernd Analphabet. Nowak kann lesen, aber nicht gut schreiben). Da Ellis","sz":9.5,"box":[53.9,671.9,283.2,768.9],"p":33,"i":7,"sec":"angriff-auf-martha"},{"t":"p","x":"von ihrer ersten Begegnung weiß, dass sie ihn nicht zu Tode singen kann, zieht sie eine Pistole. Nowak reißt sie ihr aus den Händen, wobei sie sich Prellungen zuzieht. Als es zu weiteren Handgreiflichkeiten kommt, zögert Nowak, weil er merkt, dass er nicht zu ihr durchdringen kann, und flieht. Möglicherweise wird er angeschossen und hinterlässt Blut am Tatort.","sz":9.5,"box":[309.0,59.9,538.8,144.4],"p":33,"i":8,"sec":"angriff-auf-martha"},{"t":"p","x":"Als das Team eintrifft, sitzt Ellis in eine Decke gehüllt in einem Krankenwagen. Sie ist sowohl <t>erschüttert 2</t> als auch <t>betrunken 2</t>. Fehlgeschlagene Versuche, diese Zustände zu beseitigen, können damit enden, dass die Sanitäter sie mitnehmen (<b>Ihnen etwas verweigern, das sie wollen</b>). Wie oben bei Martha (s. S. 26) erläutert, wird die Sängerin versuchen, den Vorfall zu ihrem Vorteil zu nutzen.","sz":9.5,"box":[309.0,153.1,536.6,250.1],"p":33,"i":9,"sec":"angriff-auf-martha"},{"t":"card","x":"<b>Martha behauptet, jemand habe sie angegriffen.</b> Ihre Schilderung ist korrekt mit Ausnahme des Angriffs, den sie Nowak anhängen will.","sz":null,"k":"yellow","box":[309.3,258.9,541.7,305.3],"p":33,"i":10,"sec":"angriff-auf-martha"},{"t":"card","x":"<b>Wenn man sie fragt, wie sie überlebt hat und sie das Team als Risse erkennt,</b> kann sie sich als solcher zu erkennen geben und sagen, sie habe der Magie des Mörders widerstehen können, die ihr das Leben rauben wollte.","sz":null,"k":"yellow","box":[309.3,314.5,541.7,385.9],"p":33,"i":11,"sec":"angriff-auf-martha"},{"t":"card","x":"<b>Martha behauptet, der Mörder habe persönliches Interesse an ihr.</b> Wenn sie als Riss bekannt ist, wird sie es mit der Verbindung ihrer Legenden erklären.","sz":null,"k":"yellow","box":[309.3,394.8,541.7,453.9],"p":33,"i":12,"sec":"angriff-auf-martha"},{"t":"card","x":"<b>Der Schauplatz</b> zeigt Anzeichen eines Einbruchs und Kampfes, die mit Martha Ellis‘ Aussage übereinstimmen.","sz":null,"k":"yellow","box":[309.3,462.8,541.7,509.2],"p":33,"i":13,"sec":"angriff-auf-martha"},{"t":"card","x":"<b>Jenseits des Nebels</b> hat der Ort die gleiche morastige Atmosphäre wie die anderen Tatorte. Bei genauerem Hinsehen stellt sich jedoch heraus, dass die Quelle Martha ist, nicht Nowak.","sz":null,"k":"yellow","box":[309.3,518.4,541.7,577.2],"p":33,"i":14,"sec":"angriff-auf-martha"},{"t":"card","x":"Optional kann die Polizei Nowak anhand eines Fingerabdrucks und/oder des Bluts identifizieren, falls er angeschossen wurde.Sein Vorstrafenregister zeigt eine Verurteilung wegen Körperverletzung nach einer Kneipenschlägerei vermerkt. Sein Bewährungshelfer kann auf seinen Arbeitsplatz, die <u>Schweißerei Harrington,</u> weisen. Aus der Polizeiakte oder von dem Bewährungshelfer könnte das Team auch erfahren, dass er taub ist (das würde die Lösung des Falles).","sz":null,"k":"yellow","box":[309.3,586.4,541.7,732.7],"p":33,"i":15,"sec":"angriff-auf-martha"}],"size":[595.276,841.89]},"34":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 2:","sz":14.0,"box":[53.9,61.9,122.1,75.9],"p":34,"i":0,"skip":true,"sec":"schicht-2-auf-taube-ohren"},{"t":"h","x":"AUF TAUBE OHREN","sz":23.0,"box":[53.9,84.2,228.2,107.2],"p":34,"i":1,"skip":true},{"t":"h","x":"MARTHA ELLIS‘ GARDEROBE","sz":16.0,"box":[79.7,120.8,265.0,136.8],"p":34,"i":2,"skip":true,"sec":"martha-ellis-garderobe"},{"t":"ro","x":"Die sogenannte Garderobe riecht nach welken Blumen und Alkohol. Der kleine, beengte, umgebaute Lagerraum im hinteren Teil des Washboard war wahrscheinlich das Einzige, was die Besitzer erübrigen konnten, um die Ansprüche einer Diva zu befriedigen. Die Wände sind mit Zeitungsausschnitten und Plakaten aus Marthas glorreichen Vergangenheit geschmückt. Die Bezeichnung „größte Soulstimme von Downtown“ springt euch ins Auge. Unter dem Schminktisch steht ein Eimer mit Dutzenden von kleinen Schnapsflaschen. Die arme Seele war gerade dabei, ihr Leben wieder in den Griff zu kriegen, und jetzt das.","sz":9.0,"box":[62.4,139.2,283.8,299.4],"p":34,"i":3,"sec":"martha-ellis-garderobe"},{"t":"p","x":"Die Durchsuchung von Marthas Garderobe im Washboard könnte Aufschluss über die Vergangenheit der Sängerin geben, aber sie ist schwer zugänglich. Wenn sie nicht da ist, ist die Tür <t>verschlossen 2</t>, und Sammy oder Syrus sind <t>aufmerksam 2</t> und achten darauf, dass niemand in den Hinterzimmern herumschnüffelt.","sz":9.5,"box":[53.9,308.4,280.0,380.4],"p":34,"i":4,"sec":"martha-ellis-garderobe"},{"t":"card","x":"<b>Bei einigen Zeitungsausschnitten</b> hat jemand Teile herausgeschnitten oder mit Edding geschwärzt. Ein Vergleich mit den Originalen (etwa durch eine Mikrofilm-Recherche) zeigt, dass dies die Abschnitte sind, die Ellis für ihre übermäßig emotionale Singweise kritisieren.","sz":null,"k":"yellow","box":[54.1,389.4,286.6,473.2],"p":34,"i":5,"sec":"martha-ellis-garderobe"},{"t":"card","x":"<b>Jenseits des Nebels</b> ist in der Umkleidekabine ein schwacher Abdruck des Banshee-Mythos zu sehen, dargestellt als melancholisches Moors, in dem leise eine Tin Whistle erklingt.","sz":null,"k":"yellow","box":[54.1,482.4,286.6,541.2],"p":34,"i":6,"sec":"martha-ellis-garderobe"},{"t":"p","x":"In einer verschlossenen Schublade, zwischen Andenken, liegt die Visitenkarte einer Therapeutin, <b>Dr. Selma Perrin</b>, von einem Verein namens Heilung für die Gebrochenen. Wenn das Team Dr. Perrin anruft, könnte sie Einzelheiten über Ellis‘ Vergangenheit preisgeben, um die Anrufenden loszuwerden. Wenn sie merkt, dass es sich um Risse handelt, könnte sie sie zu einem Treffen einladen (s. S. eine mögliche Begegnung mit einem Therapeuten im Fall „<i>Scherben</i>“ (s. S. 68)).","sz":10.0,"box":[62.4,555.9,271.3,691.0],"p":34,"i":7,"sec":"martha-ellis-garderobe"},{"t":"h","x":"SCHWEISSEREI HARRINGTON","sz":16.0,"box":[334.8,68.9,528.7,84.9],"p":34,"i":8,"skip":true,"sec":"schweisserei-harrington"},{"t":"ro","x":"Wenn man aus dem Stadtzentrum in diesen Teil des Industriegebiets fährt, hat das eine ernüchternde Wirkung. Dort träumt man von Geld und Berühmtheit, während die Menschen hier Tag und Nacht schuften, um über die Runden zu kommen. Die Schweißerei Harrington ist so ein Ort, eine schmierige Werkstatt, in der Kreissägen und Maschinen so laut sind, dass man sein eigenes Wort nicht versteht, aber die Augen der Beschäftigten einem auf Schritt und Tritt folgen.","sz":9.0,"box":[317.5,87.3,538.9,215.1],"p":34,"i":9,"sec":"schweisserei-harrington"},{"t":"p","x":"Die Schweißerei Harrington ist John Nowaks Arbeitsplatz, aber er ist seit einer Woche nicht mehr hier gewesen. Der Vorarbeiter, <b>Miles McFarland</b>, kann Fragen zu Nowak beantworten, aber er ist <t>misstrauisch 3</t> gegenüber dem Team und hat eine Schwäche für Nowak, weswegen er sichergehen will, dass er niemandem hilft, der Nowak schaden will. Wenn das Team ihn überzeugt, dass Nowak in die Morde verwickelt war, oder seine Firma bedroht, wird er sich vielleicht öffnen (reduziere den Zustand entsprechend).","sz":9.5,"box":[309.0,224.1,540.0,346.1],"p":34,"i":10,"sec":"schweisserei-harrington"},{"t":"card","x":"<b>John Nowak ist taubstumm.</b> Ein wichtiger Hinweis, denn er schließt aus, dass er <u>Greifer</u> angerufen hat und Gesang zum Töten benutzt.","sz":null,"k":"yellow","box":[309.3,354.5,541.7,400.9],"p":34,"i":11,"sec":"schweisserei-harrington"},{"t":"card","x":"<b>Miles hat Nowak seit jenem Nachmittag in der vergangenen Woche nicht mehr gesehen oder von ihm gehört,</b> als er sah, wie Nowak einen Jazzclub-Flyer fing und eine Weile traurig in die Ferne blickte. Dann ließ er den Flyer fallen. Miles hat ihn aufbewahrt. Es ist die Washboard-Werbung für Martha Ellis.","sz":null,"k":"yellow","box":[309.3,410.1,541.7,506.6],"p":34,"i":12,"sec":"schweisserei-harrington"},{"t":"card","x":"<b>Nowak lebt allein.</b> Seine Eltern sind vor Jahren gestorben, er hat keine Verwandten.","sz":null,"k":"yellow","box":[309.3,515.5,541.7,549.5],"p":34,"i":13,"sec":"schweisserei-harrington"},{"t":"card","x":"<b>John Nowak ist ein aufrechter Kerl, jeder in der Fabrik wird das bestätigen.</b> Die Anklage wegen Körperverletzung war das Ergebnis eines unglücklichen Vorfalls, bei dem er versuchte, einen Freund bei einer Schlägerei zu verteidigen und vor Gericht landete.","sz":null,"k":"yellow","box":[309.3,558.7,541.7,642.5],"p":34,"i":14,"sec":"schweisserei-harrington"},{"t":"card","x":"<b>John Nowak kennt das Industriegebiet gut und kann auf der Straße überleben.</b> Wenn er nicht will, dass man ihn findet, hockt er wahrscheinlich in einer verlassenen Fabrik oder einem Silo. (Details dazu, wie man ihn findet, s. <u>Nowaks Versteck.)</u>","sz":null,"k":"yellow","box":[309.3,651.7,541.7,735.6],"p":34,"i":15,"sec":"schweisserei-harrington"}],"size":[595.276,841.89]},"35":{"tab":"","blocks":[{"t":"h","x":"GREIFER","sz":16.0,"box":[103.8,74.1,159.6,90.1],"p":35,"i":0,"skip":true,"sec":"greifer"},{"t":"ro","x":"Das erste, was euch an Maurice alias Greifer auffällt, ist sein grauenerregendes Gesicht, das mit nässendem Schorf und Narben übersät ist. Dann merkt ihr, dass er eine dicke, blutverschmierte Plastikschürze trägt und ein ungewöhnlich großes Fleischerbeil mit sich herumschleppt. Ihr sagt euch, dass das für einen Metzger normal ist, fragt euch aber auch, was für ein Fleisch unter sein Messer kommt.","sz":9.0,"box":[62.4,92.5,283.8,198.7],"p":35,"i":1,"sec":"greifer"},{"t":"p","x":"<b>Maurice Alrawi</b> (Ghul), unter Kriminellen als Greifer bekannt, bietet einen Leichenbeseitigungsservice an, der keine Fragen stellt. Er arbeitet in einer alten Metzgerei im Industriegebiet, wo er die Leichen, die er entsorgen soll, aufschneidet und verschlingt. Die Leiche ist meist der Hauptbestandteil seines Lohns.","sz":9.5,"box":[53.9,207.7,283.5,279.7],"p":35,"i":2,"sec":"greifer"},{"t":"p","x":"Greifer ist ein gefräßiger Zeuge, der einen kleinen, aber entscheidenden Hinweis hat, der die Ermittlungen in eine neue Richtung lenken kann. Du kannst die Begegnung als <b>Schauplatz</b> spielen, wenn das Team ihn aufsucht, um Antworten auf den Anruf aus dem <u>Bancroft-Penthouse</u> zu erhalten. Sie kann eine <b>SL-Szene</b> sein, in der er während <u>Der nächste Mord</u> wütend auftaucht, um die versprochene Leiche zu fordern. In beiden Fällen muss das Team einen Deal mit ihm aushandeln oder zwingen, den Hinweis herauszurücken.","sz":9.5,"box":[53.9,288.3,285.6,410.3],"p":35,"i":3,"sec":"greifer"},{"t":"card","x":"<b>Die Person, die wegen der Leiche angerufen hat, hat ihre Stimme verstellt</b>, eine übliche Taktik in diesem Geschäft. (Dies deutet darauf hin, dass die Mörder:in sprechen kann, was Nowak ausschließt.)","sz":null,"k":"yellow","box":[54.1,416.2,286.6,487.6],"p":35,"i":4,"sec":"greifer"},{"t":"card","x":"<b>Greifer konnte nicht erkennen, ob es ein Mann oder eine Frau war,</b> was, wie er zugibt, ungewöhnlich ist (und darauf hindeuten könnte, dass die Anrufer:in eine gewisse Fähigkeit oder Übung im Verändern der Stimme hatte).","sz":null,"k":"yellow","box":[54.1,496.8,286.6,568.2],"p":35,"i":5,"sec":"greifer"}],"size":[595.276,841.89]},"36":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"GREIFER","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / BE- DROHEN 4","items":["<b>Ungeheuerlich:</b> Wenn Greifer einen Zustand erhält, den sein breiter Körperbau oder verrottendes Fleisch abwehren, sinkt die Stufe um 1. Wenn die SL mit Greifer Aktion ausführt, kann er zwei Ziele gleichzeitig oder ein einzelnes Ziel mit +1 treffen.","<b>Hungrig und sauer:</b> Wenn man Greifer eine Leiche verweigert, gib ihm <t>hungrig und sauer 3</t>.","<b>Totengräber:</b> Greifer kann seine Assistenten rufen (Erstelle eine neue Bedrohung: Totengräber, mit <i>Verletzen oder unschädlich machen 3</i>, Größe 1 und Messern, die <t>fiese Schnitte 2</t> verursachen).","<b>Komm zu Papa:</b> Wenn Greifer eine Leiche nicht ganz verzehrt, verwandelt sie sich in eine Ghul:in mit denselben Fähigkeiten wie er, außer, dass die Ghul:in mit den Klauen zuschlägt, nicht über die Aktion Totengräber verfügt und <i>Exorzismus 2</i> hat.","Mit seinem Hackbeil ein Körperglied angreifen (<t>Hieb 3</t>) oder eine Metallkette um jemanden wickeln und die Person mitschleifen (<t>angekettet 3</t>)","Sich gewaltsam von Fesseln befreien (bis zu 3 Stufen entfernen oder bis zu 3 Stärken verbrennen)","Fleisch fressen (<t>fieser Biss 3</t>) und so einen negativen Zustand um 1 Stufe reduzieren oder sich selbst für jede zugefügte Stufe 1 Stufe eines positiven Zustands geben","Schreien und Knurren, Blecken scharfer, blutiger gelber Zähne","Die Gestalt einer gegessenen Leiche annehmen"],"box":[62.5,57.5,137.3,73.6],"p":36,"i":0,"sec":"greifer"},{"t":"h","x":"SCHICHT 3:","sz":14.0,"box":[53.9,514.7,122.0,528.7],"p":36,"i":1,"skip":true,"sec":"schicht-3-die-totenglocke"},{"t":"h","x":"DIE TOTENGLOCKE","sz":23.0,"box":[53.9,537.1,230.0,560.1],"p":36,"i":2,"skip":true},{"t":"h","x":"NOWAKS VERSTECK","sz":16.0,"box":[79.7,573.7,212.2,589.7],"p":36,"i":3,"skip":true,"sec":"nowaks-versteck"},{"t":"ro","x":"Nowak im Industriegebiet zu finden ist wie die sprichwörtliche Suche nach der Nadel im Heuhaufen. Überall sieht man leerstehende Fabrikgebäude mit schmutzigen, zerbrochenen Glasfenstern, Betonröhrenteile und endlose Parkplätze voller LKW. Nowak könnte überall sein. In der Ferne sieht man den Rauch und Dampf, der über dem Bezirk aufsteigt, während ein Nebelhorn im nahegelegenen Hafen unangenehm wie ein Totengeläut klingt.","sz":9.0,"box":[62.4,592.0,283.8,709.0],"p":36,"i":4,"sec":"nowaks-versteck"},{"t":"p","x":"Wenn er nicht gerade Martha folgt, um sie vor ihrem drohenden Untergang zu warnen, hält sich John Nowak, der Riss des Geistes der kommenden Weihnacht, im Industriegebiet auf. Er mag taubstumm sein und","sz":9.5,"box":[53.9,718.0,279.1,765.0],"p":36,"i":5,"sec":"nowaks-versteck"},{"t":"p","x":"wenig besitzen, aber Nowak kennt die Straßen hier und ist ein erfahrener Überlebenskünstler. Zurzeit hat er sich in einer maschinell betriebenen Autofabrik niedergelassen, wo nur selten Personal vorbeikommt.","sz":9.5,"box":[309.0,59.9,536.3,106.9],"p":36,"i":6,"sec":"nowaks-versteck"},{"t":"sh","x":"<b>FINDEN DES VERSTECKS</b>","sz":9.5,"box":[309.4,115.7,436.4,125.2],"p":36,"i":7,"sec":"nowaks-versteck"},{"t":"p","x":"<b>Das Versteck zu finden wird nicht einfach sein.</b> Nowak <t>verwischte Spuren 3</t>, und jede falsche Abzweigung, die das Team in den dunklen Straßen und verlassenen Gebäuden des Industriegebiets nimmt, könnte dazu führen, dass es mit lokalen Banden, gefährlichen Fabriken oder verirrten Beschwörungen konfrontiert wird, die durch die vielen durchlässigen Stellen dringen. Die Walhalla Boys, Greifer oder eine Nemesis des Teams könnten diese Gelegenheit nutzen, um zuzuschlagen.","sz":9.5,"box":[309.0,133.8,540.0,243.3],"p":36,"i":8,"sec":"nowaks-versteck"},{"t":"sh","x":"<b>NOWAKS GEFANGENNAHME</b>","sz":9.5,"box":[309.4,252.1,454.3,261.6],"p":36,"i":9,"sec":"nowaks-versteck"},{"t":"p","x":"<b>Ist das Versteck gefunden, könnte sich die Ergreifung Nowaks als schwieriger erweisen als erwartet.</b> Wenn die SC bei Nachforschungen, um Nowak zu finden, 7-9 erzielen, kannst du ihn wissen lassen, dass sie kommen. Dann flieht er, und es kommt zur Verfolgungsjagd. Entkommt er, wird er bei <u>Der nächste Mord</u> oder Marthas Auftritt im <u>Opernhaus auftauchen.</u>","sz":9.5,"box":[309.0,270.2,538.2,354.6],"p":36,"i":10,"sec":"nowaks-versteck"},{"t":"sh","x":"<b>INTERAKTION MIT NOWAK</b>","sz":9.5,"box":[309.4,363.4,450.7,372.9],"p":36,"i":11,"sec":"nowaks-versteck"},{"t":"p","x":"Wenn das Team ihn in die Enge treibt, wird Nowak abwarten, was die SC als nächstes tun. Verdächtigt das Team Nowak zu diesem Zeitpunkt immer noch, könnte es versuchen, ihn unschädlich machen zu oder gar Rache für seine angeblichen Opfer zu nehmen und ihn zu verletzen.","sz":9.5,"box":[309.0,381.4,539.6,453.4],"p":36,"i":12,"sec":"nowaks-versteck"},{"t":"threat","stars":"★★","name":"NOWAKS VERSTECK","spectra":"NOWAKS GEFANGEN 4 / NOWAK ENTKOMMT 3","items":["<b>Fabrik-Versteck:</b> Wenn das Team Nowaks Versteck betritt, gib den SC <t>beobachtet 2</t> und Nowaks Versteck <i>Ohrenbetäubender Lärm</i>.","<b>Fäden und Stolperdrähte:</b> Wenn das Team mit <b>Heimlichkeit</b> in Nowaks Versteck herumschleicht, ohne vorher <b>Nachzuforschen</b>, bringt es sein System visueller Orientierungshilfen durcheinander. Bei 10+ oder 7-9 weiß Nowak, dass die SC kommen, aber er kann sie noch nicht sehen.","<b>Verfolgung:</b> Wenn <i>Nowak gefangen</i> den Maximalwert erreicht, ist er in die Enge getrieben. Wenn <i>Nowak entkommt</i> den Maximalwert erreicht, flieht er (<b>Ihnen etwas verweigern, das sie wollen</b>).","Einen Fluchtweg ermöglichen (gib Nowak <t>Flucht 1</t>)","Verfolger mit einer Sackgasse, einem Metallgitter oder einem eingestürzten Zahnradstapel aufhalten (entferne eine Stufe von <i>Nowak gefangen</i> oder gib jemandem <t>festsitzen 2</t>).","Lautes Scheppern und Klappern"],"box":[419.3,483.4,439.7,495.4],"p":36,"i":13,"sec":"nowaks-versteck"}],"size":[595.276,841.89]},"37":{"tab":"","blocks":[{"t":"threat","stars":"★★","name":"NOWAK","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / (VERBANNEN ODER BINDEN 4)","items":["<b>Erscheinung:</b> Wenn Nowaks <i>Verletzen oder unschädlich machen</i> den Maximalwert erreicht, stirbt er nicht oder wird ohnmächtig sondern körperlos. <i>Verletzen oder unschädlich machen</i> wird zu einer Immunität (<i>Verletzen oder unschädlich machen: –</i>), und er verliert alle Zustände. Nowak erhält <i>Verbannen oder binden: 4.</i> Da er erst lernen muss, die Fähigkeit zu kontrollieren, materialisiert er sich erst nach der nächsten Drehpause.","<b>Todesgespür:</b> Nowak kann nahenden Tod spüren und als Nebeneffekt Angriffen ausweichen, die ihn töten würden. Wenn er einen Zustand bekommt, der ihn töten würde und dem er dank Vorahnung ausweichen kann, ignoriert er ihn.","<b>Stiller Zoll:</b> Wenn Nowaks Taubheit zum ersten Mal auffällt oder relevant wird, gib ihm <i>Taub</i>. Er ist immun gegen Martha Ellis‘ Banshee-Schrei.","<b>Vorausschau:</b> Nowak ahnt die düstere Zukunft einer Person voraus, die er sehen kann, und fertigt eine grobe Skizze davon an. Beim Anblick sieht die Person, deren Zukunft abgebildet ist, das Schicksal und wird <t>emotional 3</t> oder <t>erschrocken 3</t>.","<b>Urbaner Überlebenskünstler:</b> Wenn Nowak auftritt, gib ihm <t>aufmerksam 2</t>. Am Ende jeder Drehpause findet er ein neues Versteck, wenn er sein letztes verloren hat (erstelle: Nowaks Versteck)."],"box":[64.5,57.5,125.1,73.6],"desc":"John Nowak ist ein großer, drahtiger Mann Ende 20. Er hat eine einschüchternde Ausstrahlung, sei es wegen seiner Mythos-Ausstrahlung oder wegen der gebrochenen Nase, des rasierten Schädels und seiner vielen Tätowierungen, die von kitschigen Weihnachtsmotiven bis zu gruseligen Totenköpfen, Grabsteinen und Krähen reichen. Normalerweise trägt er einen schmutzigen Kapuzenpulli über dem Tanktop, abgewetzte Cargohose und Arbeitsstiefel.","p":37,"i":0,"sec":"nowaks-versteck"},{"t":"p","x":"Die Kommunikation mit Nowak ist schwierig. Da er taubstumm und nahezu Analphabet ist, ist er ein einsamer Mann. Die meisten Kommunikationsmittel (und Stärken) funktionieren nicht, und man muss ihn beruhigen, bevor man sich nähern kann. Wenn jemand versucht, Nowaks Vertrauen zu gewinnen, gib ihm <t>ängstlich 2</t>, wenn das Team nicht aggressiv war, und <t>Angst um sein Leben 4</t>, wenn es das getan hat. Sobald er kooperativ ist, kann Nowak Ja -Nein-Fragen beantworten, auf Personen, Gegenstände oder Bilder zeigen usw.","sz":9.5,"box":[309.0,59.9,541.8,181.9],"p":37,"i":1,"sec":"nowaks-versteck"},{"t":"card","x":"<b>Als er Martha Ellis auf dem Washboard-Flyer sah, hatte Nowak eine Vision ihrer Zukunft.</b> Er bleibt vage, was die Details angeht, aber wenn man ihn drängt, könnte er eine Zeitung mit Marthas Bild und der Überschrift MÖRDE- RIN skizzieren.","sz":null,"k":"yellow","box":[309.3,192.4,541.7,276.2],"p":37,"i":2,"sec":"nowaks-versteck"},{"t":"card","x":"Nowak, der die bevorstehenden Todesfälle spürte, versuchte Martha aufzuhalten, aber er war immer zu weit weg oder kam zu spät. Er hätte näher sein müssen, um rechtzeitig eingreifen zu können, aber das Team und/oder die Polizei zwangen ihn, sich zurückzuhalten.","sz":null,"k":"yellow","box":[309.3,285.4,541.7,369.2],"p":37,"i":3,"sec":"nowaks-versteck"},{"t":"card","x":"John Nowak ist unendlich frustriert über seine Unfähigkeit zu kommunizieren und versteht nicht, warum er diese kranke Gabe der Vorahnung hat, wenn er nicht einmal jemandem helfen kann. Er ist am Rande der Verzweiflung.","sz":null,"k":"yellow","box":[309.3,378.4,541.7,449.6],"p":37,"i":4,"sec":"nowaks-versteck"},{"t":"card","x":"Nowak ist wirklich traurig und hat Mitleid mit Martha, die zu sehr in ihrem eigenen Schmerz gefangen ist, um das Leid zu erkennen, das sie anderen zufügt.","sz":null,"k":"yellow","box":[309.3,458.8,541.7,517.5],"p":37,"i":5,"sec":"nowaks-versteck"},{"t":"p","x":"• Kräftig zuschlagen (<t>taumeln 3</t>) oder jemanden packen (<t>gepackt 3</t>)","sz":9.0,"box":[64.5,566.6,256.4,587.6],"p":37,"i":6,"sec":"nowaks-versteck"},{"t":"p","x":"• Mit den Händen fuchteln und eine Warnung vor dem, was kommen wird, murmeln • Eine Vision über den Tod oder die düstere Zukunft einer Person erhalten","sz":9.0,"box":[64.5,596.6,264.0,641.6],"p":37,"i":7,"sec":"nowaks-versteck"}],"size":[595.276,841.89]},"38":{"tab":"","blocks":[{"t":"h","x":"DER NÄCHSTE MORD","sz":16.0,"box":[78.0,74.1,214.8,90.1],"p":38,"i":0,"skip":true,"sec":"der-naechste-mord"},{"t":"p","x":"Wenn das Team nichts dagegen unternimmt, wird Martha Ellis wieder zuschlagen und ein Ventil für ihre gequälte Seele suchen. Egal, ob das Team sie verdächtigt oder glaubt, sie sei das Opfer, es ist an der Zeit, einen fetten Hinweis zu geben. Diesmal kommt das Team gerade rechtzeitig, um Zeuge des Streites zwischen Ellis und Nowak zu werden.","sz":9.5,"box":[53.9,94.0,285.8,178.5],"p":38,"i":1,"sec":"der-naechste-mord"},{"t":"p","x":"Das Opfer von Martha Ellis‘ nächstem Angriff sollte jemand sein, der den SC nahe steht oder den sie mögen. Idealerweise sollte es einer der Nebenfiguren aus dem Umfeld des Teams sein. Andernfalls kann Ellis einen beliebten NSC aus dem Fall ins Visier nehmen, z. B. Sammy Jefferson Jr., Das oder Quinn usw.","sz":9.5,"box":[53.9,187.2,285.1,259.2],"p":38,"i":2,"sec":"der-naechste-mord"},{"t":"p","x":"Diese SL-Szene kann sich verschieden abspielen:","sz":9.5,"box":[53.9,267.8,260.1,277.3],"p":38,"i":3,"sec":"der-naechste-mord"},{"t":"p","x":"• Wenn Nowak auf freiem Fuß ist, kommt er rechtzeitig, um das Ende von Marthas Lied zu unterbrechen, aber sie sperrt ihn im Bad ein und hält ihn fest.","sz":9.5,"box":[53.9,288.8,282.0,323.3],"p":38,"i":4,"sec":"der-naechste-mord"},{"t":"p","x":"• Wenn Nowak eingesperrt oder Schlimmeres ist und die SC Martha verdächtigen, könnten sie nach ihr suchen und mitten in ihr Lied platzen.","sz":9.5,"box":[53.9,332.0,277.9,366.5],"p":38,"i":5,"sec":"der-naechste-mord"},{"t":"p","x":"• Wenn Nowak eingesperrt ist und die SC Martha nicht verdächtigen, können die Beamten Das oder Quinn bei Martha und dem Opfer auftauchen und die SC dann auffordern, Nachforschungen anzustellen, weil sie den falschen Mann erwischt haben könnten.","sz":9.5,"box":[53.9,375.2,285.7,434.7],"p":38,"i":6,"sec":"der-naechste-mord"},{"t":"p","x":"Der Überfall findet in der Wohnung des Opfers statt. Als das Team eintrifft, ist Martha <t>verzweifelt 3</t> und natürlich <t>betrunken 3</t>, wie beim letzten Mal. Das Opfer ist nicht tot. Das Eintreffen des Teams hat das Lied unterbrochen, es verlor das Bewusstsein und fiel ins Koma.","sz":9.5,"box":[309.0,59.9,539.7,119.4],"p":38,"i":7,"sec":"der-naechste-mord"},{"t":"card","x":"Martha weiß nicht, dass ihr Opfer nicht tot ist (nicht einmal ihr Todessinn funktioniert in ihrem Rauschzustand). Sie sieht das Opfer als tot an, bis jemand bemerkt, dass es noch lebt, woraufhin sie sehr nervös wird.","sz":null,"k":"yellow","box":[309.3,122.1,541.7,193.5],"p":38,"i":8,"sec":"der-naechste-mord"},{"t":"card","x":"Martha beharrt darauf, dass „der Kapuzenmörder“ das Opfer angegriffen hat (unabhängig davon, ob Nowak dort war oder nicht). Wenn sie erfährt, dass Nowak eingesperrt ist, wird sie sagen, es müsse ein anderer Mörder sein.","sz":null,"k":"yellow","box":[309.3,202.8,541.7,273.9],"p":38,"i":9,"sec":"der-naechste-mord"},{"t":"card","x":"Wenn man sie mit dem Lied konfrontiert, wird sie sagen, sie habe dem Opfer helfen wollen.","sz":null,"k":"yellow","box":[309.3,283.1,541.7,317.1],"p":38,"i":10,"sec":"der-naechste-mord"},{"t":"threat","stars":"★★★★","name":"MARTHA","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 1 / UM GNADE BITTEN – / EMOTIONAL HEILEN 5 / (VER- BANNEN ODER BINDEN 4)","items":["<b>Erscheinung:</b> Wenn Marthas <i>Verletzen oder unschädlich machen</i> den Maximalwert erreicht, wird sie körperlos. <i>Verletzen oder unschädlich machen</i> wird zur Immunität (<i>Verletzen oder unschädlich machen: –</i>) und alle darauf basierenden Zustände verschwinden. Sie erhält <i>Verbannen oder Binden: 4</i>. Da sie lernen muss, die Fähigkeit zu nutzen, materialisiert sie erst nach der nächsten Drehpause.","<b>Todesgespür:</b> Martha kann nahenden Tod spüren und als Nebeneffekt Angriffen ausweichen, die sie töten würden. Wenn sie einen Zustand bekommt, der sie töten würde und dem sie dank Vorahnung ausweichen kann, ignoriert sie ihn.","<b>Klage der Banshee:</b> Wenn Martha körperlos ist, ist jeder, der ihr Lied hört, so betroffen, als sänge sie über seinen persönlichen Schmerz.","<b>Alkoholikerin:</b> Wenn Martha den Schauplatz betritt, gib ihr <t>betrunken 2</t>. Als Aktion kann sie sich","selbst <t>betrunken 2</t> verleihen.","<b>Gebrochen:</b> Wenn das Team entdeckt, wie Martha Ellis wirklich fühlt, bekommt sie <t>voller Selbsthass 4</t>.","<b>Schmerz hinter den Augen:</b> Die SL kann nach dem größten Schmerz eines Charakters fragen. Martha kann die Antwort erahnen.","<b>Opernhaus-Showdown:</b> Wenn Martha für alle im Opernhaus singt, gib dem Publikum ein Spektrum von <i>Gebrochene Herzen 6</i>. Wenn der Maximalwert erreicht ist, sterben alle im Opernhaus vor Kummer.","Jemandes Schmerz besingen, wenn sie ihn kennt (<t>emotional überwältigt 4</t>, wenn das Ziel ein SC und der Schmerz mit einem Thema verbunden ist, kann er Bruch oder Verblassen markieren, um den Schmerz und Zustand loszulassen)","Jemanden mit der Kraft des Rauschs zurückstoßen (wenn sie nicht körperlos ist: <t>liegend 2</t> oder <t>blaue Flecken 2</t>)","Eine verdeckte Waffe ziehen und jemanden erschießen (<t>Schuss 3</t>)","Mikrofon schnappen"],"box":[108.8,476.3,149.6,488.3],"p":38,"i":11,"sec":"der-naechste-mord"}],"size":[595.276,841.89]},"39":{"tab":"","blocks":[{"t":"p","x":"Wenn man sie entlarvt und Konsequenzen drohen (z. B. eine Verhaftung), lässt Martha ihre Maske fallen und offenbart die rastlose Seele hinter der Fassade. Sie wird sich einen anwesenden SC aussuchen und singen, in der Hoffnung, ihre Häscher einen nach dem anderen zu Fall zu bringen und den Hass und die Wut zu entfesseln, die sie aufgestaut hat, auf die, die sie falsch verstehen und ihr auf dem Weg zu Ruhm und Ehre im Wege stehen. Wenn man ihr nicht hilft, wird sie sich erst beruhigen, wenn sie jemanden mit ihrem Klagelied getötet hat. Dann kommt sie wieder zur Vernunft und versucht zu fliehen.","sz":9.5,"box":[53.9,59.9,284.4,206.9],"p":39,"i":0,"sec":"der-naechste-mord"},{"t":"h","x":"SCHICHT 4:","sz":14.0,"box":[53.9,226.4,122.1,240.4],"p":39,"i":1,"skip":true,"sec":"schicht-4-eine-toedliche-nacht-in-der-oper"},{"t":"h","x":"EINE TÖDLICHE NACHT IN DER OPER","sz":23.0,"box":[53.9,248.7,243.5,299.7],"p":39,"i":2,"skip":true},{"t":"h","x":"DAS OPERNHAUS","sz":16.0,"box":[78.0,313.3,189.6,329.3],"p":39,"i":3,"skip":true,"sec":"das-opernhaus"},{"t":"ro","x":"„Meine Damen und Herren, willkommen im Opernhaus. Heute Abend haben wir ein ganz besonderes Line-Up von Künstler:innen, die mit uns die Magie und das Geheimnis der Jazzmusik teilen werden. Von den beliebtesten Big-Band-Songs der Stadt bis zu den verführerischsten und melancholischsten Melodien ist alles dabei. Bereiten Sie sich auf eine lange Nacht der Seele vor ... und nun, zur Eröffnung, begrüßen Sie die größte Soulstimme von Downtown, die bezaubernde Martha Ellis!","sz":9.0,"box":[62.4,331.7,283.8,459.5],"p":39,"i":4,"sec":"das-opernhaus"},{"t":"p","x":"Diese SL-Szene bietet ein grandioses Ende des Falles, wenn das Team sie noch nicht aufgehalten oder die Polizei sie aus Mangel an Beweisen freigelassen hat.","sz":9.5,"box":[53.9,468.5,278.6,503.0],"p":39,"i":5,"sec":"das-opernhaus"},{"t":"p","x":"Das Team erfährt von Marthas nächstem Auftritt: Sie wird in einer Jazznacht im Opernhaus der Stadt singen, ein entscheidender Auftritt, der dank der unermüdlichen Bemühungen Sammy Jeffersons Jr. zustande kam.","sz":9.5,"box":[53.9,511.6,286.6,558.6],"p":39,"i":6,"sec":"das-opernhaus"},{"t":"p","x":"Je nachdem, was sie bisher herausgefunden haben, könnten die SC mit unterschiedlichen Absichten in diese Szene kommen. Sie könnten Ellis aufhalten wollen, sich ihr stellen oder, falls sie sie bisher täuschen konnte, um ihrer Musik zu lauschen. Sie können zufällig davon erfahren und zum Ort des Geschehens eilen.","sz":9.5,"box":[53.9,567.3,283.7,639.3],"p":39,"i":7,"sec":"das-opernhaus"},{"t":"p","x":"<b>Martha Ellis wird sich auf der Bühne als die Banshee entpuppen, die sie ist.</b> Ihrer Gefühle ist sie sich nicht wirklich bewusst: Hass und Wut, Schuldgefühle und extreme Traurigkeit – all das kreist um eine tiefe Trauer über die Vergangenheit, die gescheiterte Karriere und die Verbrechen, die sie begangen hat. Diese Gefühle waren immer da, bei jedem Mord, und an diesem Abend werden sie sie dazu treiben, den ultimativen Auftritt, den Schwanengesang schlechthin, hinzulegen und die dunkelsten Emotionen nicht nur einer Person,","sz":9.5,"box":[53.9,648.1,285.9,770.0],"p":39,"i":8,"sec":"das-opernhaus"},{"t":"p","x":"sondern aller Menschen im Publikum offenzulegen. Wenn man sie nicht aufhält, wäre das Ergebnis eine Katastrophe, die als schmerzhafte Erinnerung in die Geschichte der Stadt eingehen wird.","sz":9.5,"box":[309.0,59.9,527.9,106.9],"p":39,"i":9,"sec":"das-opernhaus"},{"t":"p","x":"Je nach ihrer Situation und dem Wissen über Martha, können die NSC des Fall unterschiedlich angehen","sz":9.5,"box":[309.0,115.6,535.1,137.6],"p":39,"i":10,"sec":"das-opernhaus"},{"t":"p","x":"• Als Geist der kommenden Weihnacht will Nowak Ellis immer noch davor warnen, den größten Fehler ihres Lebens zu begehen und sich den Hass aller zuzuziehen. Wenn er frei ist oder sich befreien kann, wird er im Opernhaus auftauchen.","sz":9.5,"box":[309.0,149.1,539.0,208.6],"p":39,"i":11,"sec":"das-opernhaus"},{"t":"p","x":"• Sammy Jefferson Jr., der nicht weiß, welche Rolle seine Sängerin bei den Morden gespielt hat, wird in seinem schäbigsten Anzug anwesend sein. Für ihn geht es an diesem Abend darum, endlich in die Legitimität zu wechseln und richtig Geld zu verdienen. Möglicherweise ist auch Syrus eingeladen, der dann als persönlicher Leibwächter der Diva fungiert.","sz":9.5,"box":[309.0,217.3,538.2,301.8],"p":39,"i":12,"sec":"das-opernhaus"},{"t":"p","x":"• Das und Quinn könnten gerade vor dem Opernhaus den Verkehr regeln. Sie könnten den geflohenen Nowak zum Opernhaus verfolgen oder, wenn sie ein Verbrechen vermuten, dort sein, um „die Sicherheitsvorkehrungen zu überprüfen„.","sz":9.5,"box":[309.0,310.4,536.1,369.9],"p":39,"i":13,"sec":"das-opernhaus"},{"t":"h","x":"MEHR SCHERBEN","sz":14.0,"box":[323.3,396.2,404.1,410.2],"p":39,"i":14,"sec":"das-opernhaus"},{"t":"p","x":"Wenn sich in dieser Szene Marthas Wehklagen zu einem Crescendo steigert, zerspringen alle Glasgegenstände im Opernhaus – von den Buntglasfenstern bis zu den Glühbirnen –, und Scherben regnen auf das Publikum herab. Das dient vor allem als Effekt. Das Glas verursacht Panik und kleinere Kratzer, aber keinen größeren Schaden.","sz":9.0,"box":[323.3,422.7,520.7,503.7],"p":39,"i":15,"sec":"das-opernhaus"}],"size":[595.276,841.89]},"40":{"tab":"","blocks":[{"t":"h","x":"ABSPANN","sz":23.0,"box":[53.9,63.4,144.8,86.4],"p":40,"i":0,"sec":"abspann"},{"t":"p","x":"Im Folgenden findest du einige Fragen, die du dir stellen solltest, und Punkte, die es beim Abschluss dieses Falles zu überdenken gilt:","sz":9.5,"box":[53.9,97.7,282.3,132.2],"p":40,"i":1,"sec":"abspann"},{"t":"p","x":"• Was wird aus Martha Ellis? Findet sie Heilung, landet sie im Knast oder findet sie den Tod? Selbst wenn jemand einen Weg gefunden hat, die Todesfee zu bannen oder zu vernichten, könnte Marthas Gefühl einen mächtigen Abdruck hinterlassen haben, der hinter dem Schleier des Nebels weiter hallt. Wenn die SC sie noch rechtzeitig aufgehalten haben, konnten sie ihr helfen, ihre Probleme zu bewältigen? Wie kann man ihre Kräfte eindämmen? Vielleicht landet sie in der Städtischen Anstalt für kriminelle Geisteskranke, wo Dr. Krystal Knight sie therapieren wird, sodass sie als Teil des Plans zum Weltuntergang in <i>Scherben</i> (s. S. 63) wieder auftaucht.","sz":9.5,"box":[53.9,143.7,286.0,303.2],"p":40,"i":2,"sec":"abspann"},{"t":"p","x":"• Was ist mit John Nowak? War er in der Lage, Martha zu helfen und zu erreichen, was er sich vorgenommen hatte? Wenn nicht, wird er weiterhin Bösewichte davon abhalten, ihre Zukunft zu ruinieren? Hat er sich verzweifelt dem Bösen zugewandt oder ist er in den Schlaf des Nebels zurückgekehrt? Konnte er seinen Job behalten oder landet er im Gefängnis?","sz":9.5,"box":[53.9,311.9,284.0,396.4],"p":40,"i":3,"sec":"abspann"},{"t":"p","x":"• Werden Martha und Nowak durch die Ähnlichkeit ihrer Mythen und gegensätzlichen Persönlichkeiten zu Todfeinden oder entwickeln sie eine unerklärliche Liebe, die Raum, Zeit und Gitterstäbe überwindet?","sz":9.5,"box":[309.0,97.6,540.8,144.6],"p":40,"i":4,"sec":"abspann"},{"t":"p","x":"• Welche Art von Beziehung entstand zwischen dem Team und Das und Quinn: kalte Rivalität oder eine freundschaftliche Allianz? Irgendetwas dazwischen?","sz":9.5,"box":[309.0,153.3,538.6,187.8],"p":40,"i":5,"sec":"abspann"},{"t":"p","x":"• Wie endet der juristische Aspekt des Falles? Kommt jemand wegen des Todes von Darnell Fox, Tiffany Bancroft oder Adam Walsh vor Gericht? Hilft jemand den Familien der Opfer bei der Trauerarbeit oder ist es besser, sie in Frieden zu lassen? Ruhen die Seelen der Opfer oder sind sie rastlos und sinnen auf Rache?","sz":9.5,"box":[309.0,196.5,541.4,268.5],"p":40,"i":6,"sec":"abspann"},{"t":"p","x":"• Wie sieht die Zukunft des Washboard aus? Verdient Sammy Jefferson Jr. endlich ehrlich Geld, oder kehrt er zu seinen üblichen Einnahmequellen zurück?","sz":9.5,"box":[309.0,277.1,535.7,311.6],"p":40,"i":7,"sec":"abspann"}],"size":[595.276,841.89]}},"figures":[{"id":"titelbild","page":23,"kind":"art","title":"Der sanfte Tod – Titelbild","file":"img/case01/titelbild.webp","box":[0,0,595,622],"after":null},{"id":"eisberg","page":25,"kind":"eisberg","title":"Der Eisberg","file":"img/case01/eisberg.webp","box":[28,383,556,826],"after":null},{"id":"washboard","page":28,"kind":"plan","title":"Das Washboard (Grundriss)","file":"img/case01/washboard.webp","box":[10,384,587,816],"after":null},{"id":"tickets","page":29,"kind":"handout","title":"Martha Ellis – Eintrittskarten","file":"img/case01/tickets.webp","box":[30,547,298,817],"after":null},{"id":"quinn-karte","page":30,"kind":"handout","title":"Themenkarte: Das & Quinn","file":"img/case01/quinn-karte.webp","box":[55,364,294,760],"after":null},{"id":"greifer","page":35,"kind":"art","title":"Greifer","file":"img/case01/greifer.webp","box":[357,0,595,817],"after":null},{"id":"nowak-szene","page":37,"kind":"art","title":"Nowaks Welt","file":"img/case01/nowak-szene.webp","box":[0,581,595,808],"after":null},{"id":"oper","page":40,"kind":"art","title":"Das Opernhaus","file":"img/case01/oper.webp","box":[0,438,595,808],"after":null}],"eisberg":{"page":25,"fig":"eisberg","nodes":[{"label":"Sammy Jefferson Jr.","layer":0,"x":33.1,"y":56.5,"w":11,"h":9.5,"target":"das-washboard"},{"label":"Nebenrollen im Washboard","layer":0,"x":47.6,"y":56.4,"w":11,"h":9.5,"target":"das-washboard"},{"label":"Officers Das & Quinn","layer":0,"x":63.6,"y":55.0,"w":11,"h":9.5,"target":"das-quinn"},{"label":"Das Washboard","layer":1,"x":30.6,"y":63.8,"w":11,"h":9.5,"target":"das-washboard"},{"label":"Angriff auf Martha","layer":1,"x":44.2,"y":64.0,"w":11,"h":9.5,"target":"angriff-auf-martha"},{"label":"Das Bancroft-Penthouse","layer":1,"x":57.8,"y":62.5,"w":11,"h":9.5,"target":"das-bancroft-penthouse"},{"label":"Bestattungsinstitut Green Meadow","layer":1,"x":71.1,"y":61.3,"w":11,"h":9.5,"target":"bestattungsinstitut-green-meadows"},{"label":"Martha Ellis' Garderobe","layer":2,"x":37.8,"y":71.1,"w":11,"h":9.5,"target":"martha-ellis-garderobe"},{"label":"Greifer","layer":2,"x":51.1,"y":71.1,"w":11,"h":9.5,"target":"greifer"},{"label":"Schweißerei Harrington","layer":2,"x":66.1,"y":70.1,"w":11,"h":9.5,"target":"schweisserei-harrington"},{"label":"Der nächste Mord","layer":3,"x":43.3,"y":79.8,"w":11,"h":9.5,"target":"der-naechste-mord"},{"label":"Nowaks Versteck","layer":3,"x":58.7,"y":79.2,"w":11,"h":9.5,"target":"nowaks-versteck"},{"label":"Das Opernhaus","layer":4,"x":51.7,"y":87.5,"w":11,"h":9.5,"target":"das-opernhaus"}]}};
